// What the pane and the band draw (pure: no $ here; register.js reads the state, hands the values
// over with the actions the Buttons run, and registers the hooks).
//
// The pane holds the cards, the pinned ones first and each group in the order they were added: a
// title on a line of its own, then a dim line with the checklist's progress (`3/5`, `5/5 済`; only
// for a body with task-list items), 新規 or 更新 for a card Claude changed since the person's latest
// prompt (recent.js; a changed card also gets `+3 −1 行` after it), 固定, 古い and the time of the
// last write (never the card's id, which is Claude's name for it), and the body as Markdown (handed
// over as written, except that a mermaid fence mermaid.js can draw is an Svg). No button changes a
// card: the person reads, Claude writes. A long card is folded to its first lines with a secondary
// button [続きを表示（残り N 行）], an opened one has [畳む] after its body (fold.js; the view
// only). With 6 cards or more, a search field over them narrows the cards drawn to those holding
// every word typed, drawn whole while it does (search.js; the view only). With 3 cards or more, a
// secondary button beside the count switches the order to the latest write first, the pinned ones still
// first (order.js; the view only). With none, a note says
// so. A card with a single-colour
// style draws its border (bold) and title in that colour (the palette, style.js), with the setting
// `styleMarks` a shape of its own before the title (style.js SHAPES); the rainbow draws a
// stripe of seven hues across its top and its title one character a hue, the border as any card's.
// A stale card (stale.js: not pinned, not marked this turn, not written for `staleHours` hours) has
// a dim 古い before the time on its meta line, its title dim instead of its colour and its border
// dimmed (the rainbow's stripe is left out); it is only pointed out, never removed.
//
// Around the cards, the hand-over of an earlier session's board:
//   - a board that was taken over (sealed) says it is read-only above its cards, with a button
//     that makes it writable again;
//   - the line about the last hand-over, and where the cards came from;
//   - while the board is empty and other sessions' boards are there, the frame "前のセッション
//     から引き継ぐ": one board opened, several as closed rows ([中身を見る] opens one); [引き継ぐ]
//     copies its cards in, after a confirmation when the board already has cards or a card would
//     be skipped (one whose id is taken);
//   - with cards: a dim line with [表示] that opens the same frame.
// Last, a line when the store is over half full.
//
// The band is one short line, the card count (and a hint: boards to take over, or read-only) with
// a button that opens the pane, drawn at 0 cards too. Cards changed since the person's latest
// prompt add a dim `· 更新 N枚` after the count, stale cards a dim `· 古い N枚` after that. With a
// pinned card (and the setting `bandTitle` on), the title of the pinned card written last follows
// them, in its colour, with its checklist's progress. On a narrow line the title goes first, then
// 古い, then 更新; the hint stays with the label.
//
// Nothing here calls $.ui.invalidate or draws on a timer (in the desktop app every redraw
// rebuilds every mod's drawing, other mods' open panes included).

import { LIMITS, BOARD_NAME, fitBand, fitBandTitle, fitBandRecent, fitBandStale, taskProgress } from './board.js'
import { markLabel, diffLine } from './recent.js'
import { isFoldable, isFolded, foldCut, foldLabel, revOfCard } from './fold.js'
import { mermaidSvg, splitFences } from './mermaid.js'
import { RAINBOW, DEFAULT_PALETTE, colorOf, shapeOf } from './style.js'
import { stampOf, dayStampOf, cardStampOf, storeWarning, originText } from './boards.js'
import { isStaleCard, STALE_LABEL } from './stale.js'
import { SEARCH_PLACEHOLDER, SEARCH_CLEAR, SEARCH_NONE, searchCount, hasSearch, isFiltering, filterCards, inputKey } from './search.js'
import { ORDER_LABELS, hasOrder, sortCards } from './order.js'

// The pane's title is the board's name (board.js BOARD_NAME), given where register.js opens it
export const PANE_ID = 'whiteboard'

// Element keys allow a plain set of characters; a card's id is checked to, but not trusted to
const keyOf = (prefix, id) => prefix + '-' + String(id).replace(/[^A-Za-z0-9_-]/g, '_')

// The cells across a drawing: the site's own width, else what the surface measured; null when
// neither is known
export function widthOf(e) {
  const n = e.props?.bodyColumns
  if (typeof n === 'number' && n > 0) return n
  const v = e.viewport?.columns
  return typeof v === 'number' && v > 0 ? v : null
}

// A card's body. The Markdown element shows a mermaid fence as a code block, so on a surface with
// Svg the fences mermaid.js can draw become pictures, the rest of the body staying Markdown as
// written (a fence it cannot draw too). With none drawn the body is one Markdown, untouched.
function drawBody(ui, card, view) {
  const { Box, Markdown, Svg } = ui
  const whole = () => Markdown({ key: keyOf('body', card.id), text: card.body })
  if (view.surface === 'terminal' || typeof Svg !== 'function' || !/mermaid/i.test(card.body)) return whole()
  const items = []
  let drawn = 0
  const addText = (text) => {
    if (items.at(-1)?.text !== undefined) items[items.length - 1].text += '\n' + text
    else items.push({ text })
  }
  for (const piece of splitFences(card.body)) {
    const picture = piece.type === 'mermaid' ? mermaidSvg(piece.source) : null
    if (picture) {
      items.push({ picture })
      drawn++
    } else {
      addText(piece.type === 'mermaid' ? piece.raw : piece.text)
    }
  }
  if (drawn === 0) return whole()
  // About the cells of the pane less its borders and padding, at 8 pixels a cell
  const room = view.columns ? Math.max(160, (view.columns - 8) * 8) : 560
  const children = items.flatMap((item, n) => {
    if (item.text !== undefined) return item.text.trim() === '' ? [] : [Markdown({ key: keyOf('body', card.id) + '-' + n, text: item.text })]
    const { picture } = item
    const scale = Math.min(1, room / picture.width)
    return [
      Box({
        key: keyOf('diagram', card.id) + '-' + n,
        children: [Svg({ source: picture.source, alt: picture.alt, width: Math.round(picture.width * scale), height: Math.round(picture.height * scale) })],
      }),
    ]
  })
  return Box({ key: keyOf('body', card.id), flexDirection: 'column', rowGap: 1, children })
}

// The rainbow's title: one hue a character, cycling through RAINBOW; blanks take none
function rainbowTitle(ui, title) {
  const { Text } = ui
  let n = 0
  const parts = [...title].map((ch) => (/\s/.test(ch) ? ch : Text({ color: RAINBOW[n++ % RAINBOW.length], children: [ch] })))
  return Text({ bold: true, wrap: 'wrap', children: parts })
}

// The rainbow's stripe: seven Boxes side by side, one fixed hue each
function rainbowStripe(ui, card) {
  const { Box, Text } = ui
  return Box({
    key: keyOf('stripe', card.id),
    flexDirection: 'row',
    width: '100%',
    children: RAINBOW.map((hex, i) => Box({ key: keyOf('stripe', card.id) + '-' + i, flexGrow: 1, height: 1, backgroundColor: hex, children: [Text({ children: [' '] })] })),
  })
}

// A long card's button: [続きを表示（残り N 行）] when folded, [畳む] when open; it only changes the view.
// Secondary, not plain: a plain Button is drawn as bare text, which does not look pressable.
// The key says what the press does (`fold-open-<id>` / `fold-close-<id>`), so a press aimed at a
// drawing that has since been replaced (press-guard.js runs the latest drawing's closure under the
// same key) finds no handler once the card has turned the other way, rather than undoing the intent.
function drawFoldButton(ui, card, folded, remaining, onFold) {
  const { Box, Button } = ui
  return Box({
    key: keyOf('fold-row', card.id),
    flexDirection: 'row',
    children: [Button({ key: keyOf(folded ? 'fold-open' : 'fold-close', card.id), label: foldLabel(folded, remaining), variant: 'secondary', onPress: () => onFold(card.id, folded, revOfCard(card)) })],
  })
}

function drawCard(ui, card, view, onFold) {
  const { Box, Text } = ui
  const rainbow = card.style === 'rainbow'
  const color = colorOf(card.style, view.palette ?? DEFAULT_PALETTE)
  // Changed since the person's latest prompt (recent.js): a dim word, and the lines it moved
  const mark = view.marks?.[card.id]
  const marked = markLabel(mark)
  const diff = diffLine(mark)
  // Not written for a while (stale.js): a dim 古い, the title dim instead of its colour, the border dimmed, no stripe
  const stale = isStaleCard(card, view.now, view.staleHours, mark !== undefined)
  // The setting `styleMarks`: the style's shape before the title, in the title's colour (dim when stale)
  const shape = view.shapes === true ? shapeOf(card.style) : null
  const tint = stale ? { dimColor: true } : color !== null ? { color } : {}
  const words = shape !== null ? [Text({ ...tint, children: [shape] }), ' ' + card.title] : [card.title]
  const title = stale
    ? Text({ bold: true, dimColor: true, wrap: 'wrap', children: words })
    : rainbow
      ? rainbowTitle(ui, card.title)
      : Text({ bold: true, wrap: 'wrap', ...(color !== null ? { color } : {}), children: words })
  // The checklist's progress, dim like the rest of the meta line and never coloured by the style
  const progress = taskProgress(card.body)
  // The meta line under the title: dim words, the time last. The card's id is Claude's name for
  // it and is not shown.
  const meta = [
    ...(progress !== '' ? [Text({ dimColor: true, children: [progress] })] : []),
    ...(marked !== '' ? [Text({ dimColor: true, children: [marked] })] : []),
    ...(diff !== '' ? [Box({ key: keyOf('diff', card.id), children: [Text({ dimColor: true, children: [diff] })] })] : []),
    ...(card.pinned === true ? [Text({ dimColor: true, children: ['固定'] })] : []),
    ...(stale ? [Text({ dimColor: true, children: [STALE_LABEL] })] : []),
    Text({ dimColor: true, children: [cardStampOf(card.updatedAt, view.now)] }),
  ]
  const children = [
    // A stale card shows no stripe: its colours are let go like the title's
    ...(rainbow && !stale ? [rainbowStripe(ui, card)] : []),
    // The header in two lines: the title alone (wrapping), then the meta line
    Box({
      key: keyOf('head', card.id),
      flexDirection: 'column',
      children: [
        Box({ key: keyOf('title', card.id), children: [title] }),
        Box({ key: keyOf('meta', card.id), flexDirection: 'row', flexWrap: 'wrap', columnGap: 2, children: meta }),
      ],
    }),
  ]
  // A drawable mermaid fence counts as one line where the pane draws pictures (drawBody)
  const lines = { pictures: view.surface !== 'terminal' && typeof ui.Svg === 'function' }
  // While the search field narrows the cards, every card drawn is whole and has no fold button: the
  // words may have matched in the lines a fold leaves out, and a folded card would hide why it is
  // there. The person's fold choices are kept and come back once the filter is cleared.
  if (!view.filtering && isFoldable(card.body, lines)) {
    // Folded: the first lines as fold.js cuts them (never none: such a card does not fold), then the button
    const folded = isFolded(card, view.folds?.[card.id], mark !== undefined, lines)
    const cut = folded ? foldCut(card.body, lines) : null
    children.push(drawBody(ui, folded ? { ...card, body: cut.text } : card, view))
    children.push(drawFoldButton(ui, card, folded, folded ? cut.remaining : 0, onFold))
  } else if (card.body.trim() !== '') {
    children.push(drawBody(ui, card, view))
  }
  // A single-colour card has a bold border in its colour (dimmed when stale), so it stands out from
  // the thin round dim border of a card with no style and of the rainbow
  const border = color !== null ? { borderStyle: 'bold', borderColor: color, ...(stale ? { borderDimColor: true } : {}) } : { borderStyle: 'round', borderDimColor: true }
  return Box({ key: keyOf('card', card.id), flexDirection: 'column', width: '100%', ...border, paddingX: 1, children })
}

// The cards' blocks: a note and a box each, or what to ask for while there are none
function drawCards(ui, cards, view, actions) {
  const { Box, Text } = ui
  if (cards.length === 0) {
    return [
      Box({ key: 'empty', flexDirection: 'column', children: [
        Text({ wrap: 'wrap', children: ['まだ何も書かれていません'] }),
        Text({ dimColor: true, wrap: 'wrap', children: [`Claude に「${BOARD_NAME}に手順を書いて」のように頼むと、ここにカードとして残ります`] }),
      ] }),
    ]
  }
  // The fold's choice keeps only the cards on the board (fold.js foldsAfter), every one of them
  // even while the search field leaves some out, so a filter never lets a choice go
  const ids = cards.map((c) => c.id)
  const onFold = (id, open, rev) => actions.fold?.(id, open, rev, ids)
  // The search field (search.js): with enough cards and an Input the surface draws; the words
  // apply only while it is drawn
  const searching = hasSearch(cards, ui, view.surface)
  const text = searching ? view.filter ?? '' : ''
  const filtering = isFiltering(text)
  const shown = filtering ? filterCards(cards, text) : cards
  // The order button (order.js): with enough cards; with fewer the added order is drawn
  const ordering = hasOrder(cards)
  const by = ordering && view.order === 'updated' ? 'updated' : 'added'
  const count = Text({ dimColor: true, wrap: 'wrap', children: [`${cards.length} 件 · 書き換えは Claude に頼んでください`] })
  return [
    Box({
      key: 'about',
      flexDirection: 'row',
      flexWrap: 'wrap',
      columnGap: 2,
      alignItems: 'center',
      children: ordering ? [count, drawOrderButton(ui, by, actions)] : [count],
    }),
    ...(searching ? [drawSearch(ui, view.searchGen, filtering ? { total: cards.length, shown: shown.length } : null, actions)] : []),
    ...(filtering && shown.length === 0 ? [Box({ key: 'search-none', children: [Text({ wrap: 'wrap', children: [SEARCH_NONE] })] })] : []),
    ...sortCards(shown, by).map((card) => drawCard(ui, card, { ...view, filtering }, onFold)),
  ]
}

// The order button: its label names the order drawn now, a press switches to the other. Secondary,
// as the fold's: a plain Button is drawn as bare text, which does not look pressable. The key
// says what the press does (`order-updated` switches to the newest first, `order-added` back), so
// a press aimed at a replaced drawing finds no handler once the order has turned, as the fold's.
function drawOrderButton(ui, by, actions) {
  const { Button } = ui
  const to = by === 'updated' ? 'added' : 'updated'
  return Button({ key: 'order-' + to, label: ORDER_LABELS[by], variant: 'secondary', onPress: () => actions.order?.(to) })
}

// The search field over the cards; while it narrows (`count` { total, shown }), a dim line with
// the counts and a plain button that clears it. The field types live (onInput, every change) and
// Enter does the same (onSubmit, which an Input must have). The field keeps its own text (no
// `value`); [絞り込みを解く] moves `gen` on, so the field is drawn under a new key, empty (search.js).
function drawSearch(ui, gen, count, actions) {
  const { Box, Text, Button, Input } = ui
  const onText = (value) => actions.filter?.(value)
  const children = [Input({ key: inputKey(gen), placeholder: SEARCH_PLACEHOLDER, onInput: onText, onSubmit: onText })]
  if (count !== null) {
    children.push(
      Box({
        key: 'search-status',
        flexDirection: 'row',
        flexWrap: 'wrap',
        columnGap: 2,
        alignItems: 'center',
        children: [
          Text({ dimColor: true, children: [searchCount(count.total, count.shown)] }),
          Button({ key: 'search-clear', label: SEARCH_CLEAR, variant: 'secondary', onPress: () => actions.clearFilter?.() }),
        ],
      }),
    )
  }
  return Box({ key: 'search', flexDirection: 'column', children })
}

// ---- The hand-over

const boxed = (key, children) => ({ key, flexDirection: 'column', rowGap: 1, width: '100%', borderStyle: 'round', borderDimColor: true, paddingX: 1, children })

// A board that was taken over by another session: read-only here
function drawSealed(ui, sealed, actions) {
  const { Box, Text, Button } = ui
  return Box(
    boxed('sealed', [
      Text({ bold: true, children: ['読み取り専用'] }),
      Text({
        wrap: 'wrap',
        children: [`この${BOARD_NAME}は ${stampOf(sealed.at)} に、別のセッション（${sealed.toCwdName} · ID ${sealed.toSid8}）へ引き継ぎました。ここでは読むだけで、Claude も書き込めません。`],
      }),
      Box({ key: 'sealed-buttons', flexDirection: 'row', children: [Button({ key: 'unseal', label: 'このセッションで書けるように戻す', variant: 'secondary', onPress: () => actions.unseal() })] }),
      Text({ dimColor: true, wrap: 'wrap', children: ['戻しても、引き継ぎ先のカードはそのまま残ります。'] }),
    ]),
  )
}

// The line about the last hand-over or unsealing (until the pane is opened again)
function drawLast(ui, last) {
  const { Box, Text } = ui
  return Box(boxed('handover-last', [Box({ key: 'handover-last-text', children: [Text({ wrap: 'wrap', children: [last.text] })] })]))
}

// Where the cards on this board came from, for as long as the board keeps the record
function drawFrom(ui, from, now) {
  const { Box, Text } = ui
  const when = typeof from.updatedAt === 'number' ? dayStampOf(from.updatedAt, now) : '時刻不明'
  return Box({
    key: 'handover-from',
    children: [Text({ dimColor: true, wrap: 'wrap', children: [`引き継ぎ元: ${when} · ${from.cwdName} · ID ${from.sid8}（元の${BOARD_NAME}は、そのセッションを開くと読めます）`] })],
  })
}

// The first line of a board's block: when, which folder, how many cards, the id's start
function drawBoardHead(ui, b, now) {
  const { Box, Text } = ui
  return Box({
    key: keyOf('cand-head', b.sid8),
    flexDirection: 'row',
    flexWrap: 'wrap',
    columnGap: 2,
    children: [
      Text({ dimColor: true, children: [typeof b.updatedAt === 'number' ? dayStampOf(b.updatedAt, now) : '時刻不明'] }),
      Text({ bold: true, wrap: 'wrap', children: [b.cwdName] }),
      Text({ dimColor: true, children: [`${b.count} 枚`] }),
      Text({ dimColor: true, children: [`ID ${b.sid8}`] }),
    ],
  })
}

// The second line: what the session was about (its title, else the first thing typed in it)
const aboutOf = (b) => (b.title !== null ? b.title : b.firstPrompt !== null ? `「${b.firstPrompt}」` : '最初に打った言葉: 不明')

function drawBoardRow(ui, b, { open, single, hasCards, now }, actions) {
  const name = BOARD_NAME
  const { Box, Text, Button } = ui
  const children = [drawBoardHead(ui, b, now), Box({ key: keyOf('cand-about', b.sid8), children: [Text({ dimColor: true, wrap: 'wrap', children: [aboutOf(b)] })] })]
  if (open) {
    children.push(
      Box({
        key: keyOf('cand-titles', b.sid8),
        flexDirection: 'column',
        children: b.allTitles.map((t) => Text({ wrap: 'wrap', children: [`・${t.title}${t.pinned ? '（固定）' : ''}`] })),
      }),
      Box({
        key: keyOf('cand-note', b.sid8),
        flexDirection: 'column',
        children: [
          Text({
            dimColor: true,
            wrap: 'wrap',
            children: [
              hasCards
                ? `今の${name}のカードの後ろに足します。入る枚数は、押したあとの確認で分かります。`
                : `この${name}に ${b.count} 枚が入ります${b.pinnedCount > 0 ? `（固定の ${b.pinnedCount} 枚も固定のまま）` : ''}。`,
            ],
          }),
          Text({ dimColor: true, wrap: 'wrap', children: [`元の${name}は読み取り専用になり、この一覧から消えます。`] }),
        ],
      }),
    )
  } else {
    const rest = b.count - b.titles.length
    children.push(
      Box({ key: keyOf('cand-titles', b.sid8), children: [Text({ dimColor: true, wrap: 'wrap', children: [b.titles.join(' / ') + (rest > 0 ? ` ほか ${rest} 枚` : '')] })] }),
    )
  }
  const take = Button({ key: 'take-' + b.sid8, label: '引き継ぐ', variant: 'secondary', onPress: () => actions.take(b.sid8) })
  const buttons = single ? [take] : [Button({ key: 'peek-' + b.sid8, label: open ? '閉じる' : '中身を見る', variant: 'secondary', onPress: () => actions.peek(b.sid8) }), take]
  children.push(Box({ key: keyOf('cand-buttons', b.sid8), flexDirection: 'row', columnGap: 1, children: buttons }))
  return Box({ key: keyOf('cand', b.sid8), flexDirection: 'column', children })
}

// The step before a hand-over whose outcome is not plain: what goes in, what is skipped, what does not fit
function drawConfirm(ui, b, confirm, now, actions) {
  const { Box, Text, Button } = ui
  const name = BOARD_NAME
  const { added, duplicates, overflow } = confirm.plan
  // The card limit the plan was made with (the setting `maxCards`); a step staged before it was kept: the default
  const limit = Number.isSafeInteger(confirm.plan.limit) ? confirm.plan.limit : LIMITS.cards
  // By title only: a card's id is Claude's name for it and is not shown in the pane
  const entries = (list, key) => Box({ key, flexDirection: 'column', children: list.map((c) => Text({ wrap: 'wrap', children: [`  ・${c.title}`] })) })
  const pinned = added.filter((c) => c.pinned).length
  const children = [Text({ bold: true, children: ['引き継ぐ前に確認してください'] })]
  if (confirm.recounted) children.push(Text({ wrap: 'wrap', children: [`${name}が変わったので、数え直しました`] }))
  children.push(Text({ wrap: 'wrap', children: [`${originText(b, now)} · ${b.count} 枚 · ID ${b.sid8} から`] }))
  if (added.length > 0) {
    children.push(Text({ wrap: 'wrap', children: [`入る: ${added.length} 枚`] }))
    if (pinned > 0) children.push(Text({ dimColor: true, wrap: 'wrap', children: [`固定の ${pinned} 枚も固定のまま入ります`] }))
  }
  if (duplicates.length > 0) {
    children.push(Text({ wrap: 'wrap', children: [`飛ばす: ${duplicates.length} 枚（今の${name}か最近消したカードに、同じカードがあるため。今のカードはそのまま）`] }), entries(duplicates, 'confirm-skipped'))
  }
  if (overflow.length > 0) {
    children.push(Text({ wrap: 'wrap', children: [`入らない: ${overflow.length} 枚（カードは ${limit} 枚まで）`] }), entries(overflow, 'confirm-overflow'))
    children.push(Text({ dimColor: true, wrap: 'wrap', children: [`入らなかったカードは元の${name}に残り、そのセッションを開けば読めます。`] }))
  }
  const buttons = []
  if (added.length > 0) {
    buttons.push(Button({ key: 'take-confirm', label: 'この内容で引き継ぐ', variant: 'secondary', onPress: () => actions.takeConfirm() }))
  } else {
    // Nothing would go in: say why, and leave only the way out
    const why =
      overflow.length > 0
        ? `今の${name}は ${limit} 枚でいっぱいなので、1 枚も入りません。済んだカードを消してから引き継いでください`
        : `入るカードが 1 枚もありません（すべて、今の${name}か最近消したカードに同じカードがあります）`
    children.push(Text({ wrap: 'wrap', children: [why] }))
  }
  buttons.push(Button({ key: 'take-cancel', label: 'やめる', variant: 'secondary', onPress: () => actions.takeCancel() }))
  children.push(Box({ key: 'confirm-buttons', flexDirection: 'row', columnGap: 1, children: buttons }))
  return Box(boxed('confirm', children))
}

// The frame "前のセッションから引き継ぐ": the boards that may be taken over
function drawHandover(ui, others, hasCards, view, now, actions) {
  const { Box, Text } = ui
  const name = BOARD_NAME
  const single = others.boards.length === 1
  const rows = others.boards.flatMap((b) => {
    const row = drawBoardRow(ui, b, { open: single || view.pick === b.sid8, single, hasCards, now }, actions)
    return view.confirm !== null && view.confirm.sid8 === b.sid8 ? [row, drawConfirm(ui, b, view.confirm, now, actions)] : [row]
  })
  return Box(
    boxed('handover', [
      Text({ bold: true, children: ['前のセッションから引き継ぐ'] }),
      Text({ dimColor: true, wrap: 'wrap', children: [`前のセッションの${name}のカードを、この${name}に写します。元の${name}は消えずに残り、読み取り専用になります。`] }),
      ...(others.notice !== '' ? [Box({ key: 'handover-notice', children: [Text({ wrap: 'wrap', children: [others.notice] })] })] : []),
      ...rows,
      ...(others.more > 0 ? [Box({ key: 'handover-more', children: [Text({ dimColor: true, children: [`ほか ${others.more} 件`] })] })] : []),
    ]),
  )
}

// With cards on the board: one dim line and a button that opens the frame
function drawEntry(ui, others, view, actions) {
  const { Box, Text, Button } = ui
  return Box({
    key: 'handover-entry',
    flexDirection: 'row',
    flexWrap: 'wrap',
    columnGap: 2,
    alignItems: 'center',
    children: [
      Text({ dimColor: true, wrap: 'wrap', children: [`前のセッションの${BOARD_NAME}を引き継ぐこともできます（${others.boards.length + others.more} 件）`] }),
      Button({ key: 'show-handover', label: view.shown ? '隠す' : '表示', variant: 'secondary', onPress: () => actions.toggleShown() }),
    ],
  })
}

/**
 * The pane's tree. `data` is what register.js read from $.state: { cards, others, handover:
 * { sealed, from, last }, view: { pick, shown, confirm, searchGen (search.js inputKey) }, enabled (the setting `handover`),
 * now, palette (style.js), marks (recent.js: the cards changed since the
 * person's latest prompt, by id), folds (fold.js: the person's fold choices, by id), filter
 * (search.js: the search field's text, '' for none), order (order.js: 'added' or 'updated'), ownBytes
 * (the JSON size of this session's keys as stored, the cards' previous versions and the removed
 * cards included; null when unknown, the shown cards are counted then), staleHours (stale.js: the
 * setting, 0 for off), shapes (style.js: the setting `styleMarks`) }; `where` is
 * { surface, columns }; `actions` the Buttons' work.
 */
export function drawPane(ui, data, where, actions) {
  const { cards, others, handover, view, enabled, now, palette, marks = {}, folds = {}, filter = '', order = 'added', ownBytes = null, staleHours = 0, shapes = false } = data
  const { Box, Text } = ui
  const sealed = handover.sealed !== null
  const offered = enabled && !sealed
  const warning = storeWarning(others.bytes + (typeof ownBytes === 'number' ? ownBytes : JSON.stringify(cards).length))
  const children = [
    ...(sealed ? [drawSealed(ui, handover.sealed, actions)] : []),
    ...(handover.last !== null ? [drawLast(ui, handover.last)] : []),
    ...(handover.from !== null ? [drawFrom(ui, handover.from, now)] : []),
    ...drawCards(ui, cards, { ...where, now, palette, marks, folds, filter, order, searchGen: view.searchGen ?? 0, staleHours, shapes }, actions),
    ...(offered && cards.length === 0 && (others.boards.length > 0 || others.notice !== '') ? [drawHandover(ui, others, false, view, now, actions)] : []),
    ...(offered && cards.length > 0 && (others.boards.length > 0 || view.shown) ? [drawEntry(ui, others, view, actions)] : []),
    ...(offered && cards.length > 0 && view.shown ? [drawHandover(ui, others, true, view, now, actions)] : []),
    ...(warning !== '' ? [Box({ key: 'store-warning', children: [Text({ dimColor: true, wrap: 'wrap', children: [warning] })] })] : []),
  ]
  return ui.Box({ key: 'whiteboard', flexDirection: 'column', rowGap: 1, paddingX: 1, width: '100%', children })
}

// The band's "· title progress": the title in the card's single colour (the rainbow and no style
// plain), the progress dim. The only part that may shrink: its Text cuts at the edge with an
// ellipsis should the estimate of the line's room be short.
function drawBandTitle(ui, part, color, shape) {
  const { Box, Text } = ui
  const tint = color !== null ? { color } : {}
  return Box({
    key: 'board-title',
    flexShrink: 1,
    minWidth: 0,
    children: [
      Text({
        wrap: 'truncate-end',
        children: [
          '· ',
          // The setting `styleMarks`: the style's shape before the title, in the same colour
          ...(shape !== null ? [Text({ ...tint, children: [shape + ' '] })] : []),
          Text({ ...tint, children: [part.title] }),
          ...(part.progress !== '' ? [Text({ dimColor: true, children: [' ' + part.progress] })] : []),
        ],
      }),
    ],
  })
}

/**
 * The band's tree; `hint` is '' or the few words after the count; `onOpen` is what [開く] does.
 * `card` is the pinned card whose title follows the counts (board.js bandCard), or null; `palette`
 * gives its colour (style.js); `changed` is how many cards on the board were changed since the
 * person's latest prompt (a dim `· 更新 N枚` after the label); `stale` how many cards are stale
 * (stale.js: a dim `· 古い N枚` after it). The room goes to the label and [開く], then 更新, then
 * 古い, then the title, which is the first to go. `shapes` is the setting `styleMarks` (the
 * style's shape before the title).
 */
export function drawBand(ui, surface, columns, count, hint, onOpen, { card = null, palette = DEFAULT_PALETTE, changed = 0, stale = 0, shapes = false } = {}) {
  const { Box, Text, Button } = ui
  const fit = fitBand({ surface, columns, count, hint })
  // The room goes to 更新 first, then 古い, then the title (board.js)
  const recent = fitBandRecent({ surface, columns, count, hint, changed })
  const old = fitBandStale({ surface, columns, count, hint, recent, stale })
  const shape = card !== null && shapes === true ? shapeOf(card.style) : null
  const part = card !== null ? fitBandTitle({ surface, columns, count, hint, title: card.title, progress: taskProgress(card.body), recent, old, shape: shape ?? '' }) : null
  const children = []
  if (fit.hasLabel) children.push(Box({ key: 'board-label', flexShrink: 0, children: [Text({ children: [fit.label] })] }))
  if (recent !== '') children.push(Box({ key: 'board-recent', flexShrink: 0, children: [Text({ dimColor: true, children: [recent] })] }))
  if (old !== '') children.push(Box({ key: 'board-stale', flexShrink: 0, children: [Text({ dimColor: true, children: [old] })] }))
  if (part !== null) children.push(drawBandTitle(ui, part, colorOf(card.style, palette), shape))
  children.push(
    Box({ key: 'board-open-slot', flexShrink: 0, children: [Button({ key: 'board-open', label: fit.buttonLabel, variant: 'secondary', onPress: onOpen })] }),
  )
  return Box({ key: 'whiteboard-band', flexDirection: 'row', flexWrap: 'nowrap', columnGap: 1, alignItems: 'center', children })
}

files.hooks/recent.js:
// Which cards Claude changed since the person's latest prompt (pure: no $ here).
//
// The person's prompts count turns: each one moves the counter on (`turn` in $.state, with the
// session it belongs to). A tool write that changes a card marks it for the current turn: a card
// that was not on the board before the turn's first write to it is new, any other changed. A
// changed card also keeps the body it had before that first write (its base), so the line count
// sums the whole turn, not only the last write. The marks live in the load and are mirrored into
// $.state (`recent`, without the bases) for the drawings; the drawings show them only while their
// turn is the current one, so the next prompt clears them without a write. A counter that is not
// there (never set, or lost) means no marks: nothing is marked and nothing is shown.

import { sameContent } from './board.js'

// The `source` of a classic UserPromptSubmit that counts as the person's own prompt: the composer
// (`user`), an SDK host's turn (`sdk`), or none (older payloads). Whether the desktop app sends
// `sdk` for the person's prompts is not verified; it is accepted so that they count if it does.
const PERSON_SOURCES = new Set(['user', 'sdk'])

/**
 * Whether a classic UserPromptSubmit is the person's own prompt (not a wake-up, a notification or
 * an enqueue pass). One rule for every use: the turns of the marks, the first request kept for the
 * meta, and the guide's lines.
 */
export const isPersonPrompt = (e) => e != null && (e.source === undefined || PERSON_SOURCES.has(e.source))

const isTurn = (n) => Number.isSafeInteger(n) && n > 0

/** The current turn of the `turn` state value for the session `owner`; null when there is none. */
export function readTurn(value, owner) {
  if (value == null || typeof value !== 'object' || value.owner !== owner || !isTurn(value.n)) return null
  return value.n
}

/** The `turn` state value after a prompt: one more than this session's, 1 when there is none. */
export const turnAfter = (value, owner) => ({ owner, n: (readTurn(value, owner) ?? 0) + 1 })

// ---- The line count

// A body's lines; a last newline ends the last line rather than starting an empty one
function linesOf(text) {
  const s = String(text ?? '')
  if (s === '') return []
  const lines = s.split(/\r?\n/)
  if (lines.at(-1) === '') lines.pop()
  return lines
}

// Above this many cells (lines before x lines after, once the common ends are cut), the lines are
// matched as multisets rather than in order
const LCS_CELLS = 250_000

// The length of the longest common subsequence of two lists of lines
function lcsLength(a, b) {
  const row = new Array(b.length + 1).fill(0)
  for (let i = 1; i <= a.length; i++) {
    let diag = 0
    for (let j = 1; j <= b.length; j++) {
      const up = row[j]
      row[j] = a[i - 1] === b[j - 1] ? diag + 1 : Math.max(row[j], row[j - 1])
      diag = up
    }
  }
  return row[b.length]
}

// How many lines the two lists share, order not looked at
function sharedCount(a, b) {
  const counts = new Map()
  for (const line of a) counts.set(line, (counts.get(line) ?? 0) + 1)
  let shared = 0
  for (const line of b) {
    const n = counts.get(line) ?? 0
    if (n > 0) {
      shared++
      counts.set(line, n - 1)
    }
  }
  return shared
}

/**
 * The lines added and removed from `before` to `after`: { added, removed }. A changed line counts
 * as one removed and one added. The lines the two share at their start and end are cut first, the
 * rest matched in order (a longest common subsequence), or as multisets when that would be large.
 */
export function lineDiff(before, after) {
  const a = linesOf(before)
  const b = linesOf(after)
  let start = 0
  while (start < a.length && start < b.length && a[start] === b[start]) start++
  let endA = a.length
  let endB = b.length
  while (endA > start && endB > start && a[endA - 1] === b[endB - 1]) {
    endA--
    endB--
  }
  const x = a.slice(start, endA)
  const y = b.slice(start, endB)
  const common = x.length === 0 || y.length === 0 ? 0 : x.length * y.length <= LCS_CELLS ? lcsLength(x, y) : sharedCount(x, y)
  return { added: y.length - common, removed: x.length - common }
}

// ---- The marks: { [card id]: { base, added, removed } }, base null for a new card (no counts),
// else the card as it was before the turn's first write to it ({ title, body, pinned, style })

// A card's version as a base keeps it
const baseOf = (c) => ({ title: c.title, body: c.body, pinned: c.pinned === true, style: c.style ?? null })

/**
 * The marks after a write that turned `before` into `after`: each card that is new or says
 * something else than it did is marked. A card marked earlier in the turn keeps its base, so its
 * counts compare the body before the turn's first write with the body now, and a card that says
 * again what its base said (undone back to the turn's start) loses its mark; a base not known
 * (undefined, marks taken back from the state after a reload) falls back to the card before this
 * write. Marks of cards that are gone stay (a card removed and brought back in the same turn keeps
 * its base). The same object when nothing changed.
 */
export function markWrite(marks, before, after) {
  const was = new Map(before.map((c) => [c.id, c]))
  let next = marks
  const put = (id, mark) => {
    if (next === marks) next = { ...marks }
    if (mark === undefined) delete next[id]
    else next[id] = mark
  }
  for (const c of after) {
    const old = was.get(c.id)
    if (old && sameContent(old, c)) continue
    const had = marks[c.id]
    const base = had !== undefined && had.base !== undefined ? had.base : old ? baseOf(old) : null
    if (base !== null && sameContent(base, c)) {
      if (had !== undefined) put(c.id, undefined)
      continue
    }
    put(c.id, base === null ? { base: null } : { base, ...lineDiff(base.body, c.body) })
  }
  return next
}

/** The marks as $.state keeps them for the drawings: { kind: 'new' } or { kind: 'changed', added, removed }, no bases. */
export function shownMarks(marks) {
  const out = {}
  for (const [id, m] of Object.entries(marks)) out[id] = m.base === null ? { kind: 'new' } : { kind: 'changed', added: m.added, removed: m.removed }
  return out
}

const isCount = (n) => Number.isSafeInteger(n) && n >= 0

// A state mark that is well-formed, else null
function readMark(m) {
  if (m == null || typeof m !== 'object') return null
  if (m.kind === 'new') return { kind: 'new' }
  if (m.kind === 'changed' && isCount(m.added) && isCount(m.removed)) return { kind: 'changed', added: m.added, removed: m.removed }
  return null
}

/**
 * The marks of the `recent` state value when it is this session's and of the turn `turn`, else {}.
 * Entries of another shape are left out.
 */
export function marksOf(value, owner, turn) {
  if (turn === null || value == null || typeof value !== 'object' || value.owner !== owner || value.turn !== turn) return {}
  const cards = value.cards
  if (cards == null || typeof cards !== 'object' || Array.isArray(cards)) return {}
  const out = {}
  for (const [id, m] of Object.entries(cards)) {
    const mark = readMark(m)
    if (mark !== null) out[id] = mark
  }
  return out
}

/** The load's marks taken back from the state (after a reload): new ones keep base null, changed ones an unknown base. */
export function seedMarks(shown) {
  const out = {}
  for (const [id, m] of Object.entries(shown)) out[id] = m.kind === 'new' ? { base: null } : { base: undefined, added: m.added, removed: m.removed }
  return out
}

/** How many of the cards on the board are marked. */
export const markedCount = (marks, cards) => (Array.isArray(cards) ? cards.filter((c) => marks[c?.id] !== undefined).length : 0)

/** The header's word for a mark: 新規 or 更新; '' for none. */
export const markLabel = (mark) => (mark == null ? '' : mark.kind === 'new' ? '新規' : '更新')

/** The line under the header of a changed card, `+3 −1 行`; '' for a new card, none, or a change that moved no line. */
export function diffLine(mark) {
  if (mark?.kind !== 'changed' || mark.added + mark.removed === 0) return ''
  return `+${mark.added} −${mark.removed} 行`
}

files.hooks/style.js:
// A card's style: a colour by hue name, or the decorative rainbow (pure: no $ here).
//
// The names are hues only; no colour carries a meaning here. Claude may name one of STYLES and
// nothing else (no raw colour codes, no theme keys). The seven single colours draw through a
// palette: a theme key each by default, so they follow the person's light or dark theme, and the
// setting `colors` may point any of them at another theme key or a hex code, so that the person
// can pick colours they tell apart. The rainbow (see HIDDEN) is fixed and not touched by the setting.

/** The single-colour styles, in the order the tools list them. */
export const COLOR_NAMES = ['red', 'orange', 'yellow', 'green', 'blue', 'purple', 'gray']

// The rainbow is an easter egg: accepted and drawn, but never named to Claude or the person: not
// in the tools' schemas and descriptions, the error that lists the names, the README, the skill
// (SKILL.md), plugin.json or types/index.d.ts
const HIDDEN = ['rainbow']

/** Every style a card may carry. */
export const STYLES = [...COLOR_NAMES, ...HIDDEN]

/** The names the tools and the error list: the single colours and `none` (which removes the style). */
export const STYLE_INPUTS = [...COLOR_NAMES, 'none']

/** The default theme key of each single colour. */
export const DEFAULT_PALETTE = {
  red: 'error',
  orange: 'claude',
  yellow: 'warning',
  green: 'success',
  blue: 'suggestion',
  purple: 'merged',
  gray: 'inactive',
}

/** The rainbow's seven fixed hues: red, orange, yellow, green, blue, indigo, violet. */
export const RAINBOW = ['#E53935', '#FB8C00', '#FDD835', '#43A047', '#1E88E5', '#3949AB', '#8E24AA']

// The theme keys the engine names (ThemeKey); the setting may use any of them, in any case
const THEME_KEYS = [
  'text', 'inverseText', 'inactive', 'subtle', 'suggestion', 'remember', 'success', 'error', 'warning', 'merged', 'claude',
  'permission', 'planMode', 'autoAccept', 'promptBorder', 'bashBorder', 'ide', 'diffAdded', 'diffRemoved', 'diffAddedDimmed',
  'diffRemovedDimmed', 'diffAddedWord', 'diffRemovedWord',
]
const THEME_BY_LOWER = new Map(THEME_KEYS.map((k) => [k.toLowerCase(), k]))
const HEX = /^#(?:[0-9a-f]{3}|[0-9a-f]{6})$/i

/** A stored style that is one of STYLES; anything else (none, absent, broken) is no style. */
export const isStyle = (value) => typeof value === 'string' && STYLES.includes(value)

/** The style a card (or a version of one) carries: one of STYLES, else null. */
export const styleOf = (c) => (isStyle(c?.style) ? c.style : null)

/**
 * A tool's `style` input: { keep: true } when absent, { style: null } for none, { style } for one
 * of STYLES, or { error } that lists the names.
 */
export function styleInput(value) {
  if (value === undefined) return { keep: true }
  if (value === 'none') return { style: null }
  if (isStyle(value)) return { style: value }
  return { error: `style は ${STYLE_INPUTS.join(' / ')} のどれかで指定してください（色コードやほかの語は使えません。none で色を外します）` }
}

/** The colour a value of the setting names: a theme key (its own spelling) or a hex code; null for anything else. */
function colorValue(text) {
  const v = text.trim()
  if (HEX.test(v)) return v
  return THEME_BY_LOWER.get(v.toLowerCase()) ?? null
}

/**
 * The palette from the setting `colors` ("red=#D55E00, green=#009E73, blue=suggestion"): the
 * defaults with each well-formed entry laid over. An entry with an unknown name or a value that is
 * neither a theme key nor #rgb / #rrggbb is let go by itself.
 */
export function paletteOf(options = {}) {
  const palette = { ...DEFAULT_PALETTE }
  const text = options?.colors
  if (typeof text !== 'string') return palette
  for (const entry of text.split(/[,\n;]/)) {
    const at = entry.indexOf('=')
    if (at < 0) continue
    const name = entry.slice(0, at).trim().toLowerCase()
    if (!COLOR_NAMES.includes(name)) continue
    const color = colorValue(entry.slice(at + 1))
    if (color !== null) palette[name] = color
  }
  return palette
}

/** The colour a single-colour style draws with; null for no style and for the rainbow. */
export const colorOf = (style, palette = DEFAULT_PALETTE) => (COLOR_NAMES.includes(style) ? palette[style] ?? DEFAULT_PALETTE[style] : null)

// The setting `styleMarks`: a small shape before a single-colour card's title, one per name, for
// people who do not tell the colours apart. Tied to the name, not to the colour `colors` gives it,
// so a shape keeps its meaning whatever the palette. Geometric shapes and dingbats with no emoji
// presentation (a plain text glyph in any font that has them; no variation selector needed).
export const SHAPES = {
  red: '●', // U+25CF black circle
  orange: '▲', // U+25B2 black up-pointing triangle
  yellow: '◆', // U+25C6 black diamond
  green: '■', // U+25A0 black square
  blue: '★', // U+2605 black star
  purple: '✚', // U+271A heavy greek cross
  gray: '○', // U+25CB white circle
}

/** The setting `styleMarks`: off unless true. */
export const shapesOn = (options) => options?.styleMarks === true

/** The shape of a single-colour style; null for no style and for the rainbow. */
export const shapeOf = (style) => (COLOR_NAMES.includes(style) ? SHAPES[style] : null)

files.hooks/fold.js:
// Long cards folded in the pane (pure). A view only: the cards are never changed, the pane just
// shows the first lines of a long body and a button that opens the rest.
//
// A body is long past FOLD.lines lines (blank lines at its end not counted). Where the pane draws
// pictures (`pictures`: not the terminal), a mermaid fence that mermaid.js can draw counts as one
// line, a picture being compact; a fence it cannot draw stays code and counts its source lines. A
// folded card shows at most FOLD.preview source lines, cut at a line boundary that is never inside
// a fenced code block: a fence that crosses the cut moves the cut to just before the fence (a fence
// closed before it stays whole). A cut that would leave nothing to show does not fold at all: the
// card is drawn whole, with no button.
//
// Whether a long card is folded: what the person chose with the button, else unfolded for a
// pinned card (people pin what they want to see) and folded for the rest. A card Claude changed
// in the current turn (recent.js) is shown unfolded so the change is seen, unless the person
// folded it again after that write (the choice keeps the card's revision, `rev`, it was made at;
// every write that changes a card moves it on). The choices live in the view state for the
// session (`folds`: { owner, cards: { id: { open, rev } } }); every write to the board lets go of
// the choices of cards no longer on it (foldsKept), so a new card under a removed one's id starts
// afresh.

import { mermaidSvg } from './mermaid.js'

export const FOLD = { lines: 12, preview: 6 }

// The body's lines: CRLF read as LF, the blank lines at the end left off
function linesOf(body) {
  const lines = String(body ?? '').replace(/\r\n?/g, '\n').split('\n')
  while (lines.length > 0 && lines[lines.length - 1].trim() === '') lines.pop()
  return lines
}

// The fenced code blocks of `lines` as { first, last, picture } (line indexes). A fence opens with
// three or more backticks or tildes (up to three spaces before; a backtick fence's info string has
// no backtick) and closes with a run of the same character at least as long; one never closed runs
// to the end, as Markdown reads it. `picture` is true for a closed ```mermaid fence that mermaid.js
// can draw, when `pictures` is on.
function fencesOf(lines, pictures = false) {
  const blocks = []
  let i = 0
  while (i < lines.length) {
    const open = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(lines[i])
    if (!open || (open[1][0] === '`' && open[2].includes('`'))) {
      i++
      continue
    }
    const fence = open[1]
    let last = lines.length - 1
    let closed = false
    for (let j = i + 1; j < lines.length; j++) {
      const close = /^ {0,3}(`{3,}|~{3,})\s*$/.exec(lines[j])
      if (close && close[1][0] === fence[0] && close[1].length >= fence.length) {
        last = j
        closed = true
        break
      }
    }
    const picture = pictures && closed && open[2].trim().toLowerCase() === 'mermaid' && mermaidSvg(lines.slice(i + 1, last).join('\n')) !== null
    blocks.push({ first: i, last, picture })
    i = last + 1
  }
  return blocks
}

// The lines a run of fences saves when each picture counts as one line
const savedBy = (blocks) => blocks.reduce((n, b) => n + (b.picture ? b.last - b.first : 0), 0)

/**
 * The lines of a body, as the fold counts them. With `pictures` (the pane draws them), a mermaid
 * fence that can be drawn counts as one line.
 */
export function bodyLines(body, { pictures = false } = {}) {
  const lines = linesOf(body)
  return lines.length - savedBy(fencesOf(lines, pictures))
}

/** True for a body long enough to fold (bodyLines past FOLD.lines). */
export const isLong = (body, options = {}) => bodyLines(body, options) > FOLD.lines

/**
 * The folded view of a body: `text`, the lines shown ('' for none), and `remaining`, the lines
 * left out (the button's count; with `pictures`, a drawable mermaid fence left out counts as one).
 */
export function foldCut(body, { pictures = false } = {}) {
  const lines = linesOf(body)
  const blocks = fencesOf(lines, pictures)
  let cut = Math.min(FOLD.preview, lines.length)
  for (const { first, last } of blocks) {
    if (first >= cut) break
    if (last >= cut) {
      cut = first
      break
    }
  }
  const shown = lines.slice(0, cut)
  while (shown.length > 0 && shown[shown.length - 1].trim() === '') shown.pop()
  return { text: shown.join('\n'), remaining: lines.length - cut - savedBy(blocks.filter((b) => b.first >= cut)) }
}

/** Whether a body folds at all: long, and its folded view leaves something to show. */
export const isFoldable = (body, options = {}) => isLong(body, options) && foldCut(body, options).text.trim() !== ''

/** A card's revision as a choice keeps it (0 for a card written before revisions existed). */
export const revOfCard = (card) => (typeof card.rev === 'number' ? card.rev : 0)

/**
 * Whether `card` is drawn folded: never when its body does not fold (isFoldable, with `options`
 * { pictures }); else the person's `choice` ({ open, rev } or undefined), which a card `marked` in
 * the current turn takes only when it was made after the card's latest write; else unfolded when
 * marked or pinned, folded otherwise.
 */
export function isFolded(card, choice, marked, options = {}) {
  if (!isFoldable(card.body, options)) return false
  if (choice && (!marked || choice.rev === revOfCard(card))) return !choice.open
  if (marked) return false
  return card.pinned !== true
}

const isChoice = (c) => c != null && typeof c === 'object' && typeof c.open === 'boolean' && typeof c.rev === 'number'

/** The choices of the session `me` from the view state's `folds` value; {} for none or another session's. */
export function foldsOf(value, me) {
  if (value == null || typeof value !== 'object' || value.owner !== me) return {}
  const cards = value.cards != null && typeof value.cards === 'object' ? value.cards : {}
  const out = {}
  for (const [id, c] of Object.entries(cards)) if (isChoice(c)) out[id] = { open: c.open, rev: c.rev }
  return out
}

/**
 * The `folds` value with only the choices of the cards in `ids` (the cards on the board), so a
 * removed card's choice goes and a later card under the same id starts afresh. null for no value.
 */
export function foldsKept(value, me, ids) {
  if (value == null || typeof value !== 'object') return null
  const keep = new Set(ids)
  const cards = {}
  for (const [k, c] of Object.entries(foldsOf(value, me))) if (keep.has(k)) cards[k] = c
  return { owner: me, cards }
}

/**
 * The `folds` value after the person chose `open` for the card `id` (at its revision `rev`). Only
 * the cards in `ids` (the ones the pane drew) keep their choices, so a removed card's goes.
 */
export function foldsAfter(value, me, id, open, rev, ids) {
  const keep = new Set(ids)
  const cards = {}
  for (const [k, c] of Object.entries(foldsOf(value, me))) if (keep.has(k)) cards[k] = c
  cards[id] = { open, rev }
  return { owner: me, cards }
}

/** The button's label: the lines left out on a folded card, 畳む on an open one. */
export const foldLabel = (folded, remaining) => (folded ? `続きを表示（残り ${remaining} 行）` : '畳む')

files.hooks/search.js:
// The pane's search field (pure): the person narrows the cards drawn by words, the view only.
// Nothing about the cards changes and nothing is stored: the text lives in the view state for the
// session (`filter`: { owner, text }), so after /clear (another session id) it reads as none.
//
// The field is drawn only when there are SEARCH_MIN cards or more (fewer need no search) and the
// surface draws an Input (not the mobile app). The filter applies only while the field is drawn, so it never hides cards
// with no field to undo it; it is let go when the pane is opened and when the board falls below
// SEARCH_MIN cards (register.js), so an old filter does not come back unnoticed. The words are split as list_cards' query splits them (board.js
// queryTerms) and matched much as its searchCards does (every word, any case, part of a word), but in
// the title and body only: the pane does not show a card's id, so a card must not match on a word the
// person cannot see.

import { queryTerms } from './board.js'

/** The fewest cards that bring the search field. */
export const SEARCH_MIN = 6

/** The field's placeholder, the clear button's label, the line when nothing matches. */
export const SEARCH_PLACEHOLDER = 'カードを絞り込む（語を空白で区切る）'
export const SEARCH_CLEAR = '絞り込みを解く'
export const SEARCH_NONE = '一致するカードはありません'

/** The dim line under the field while it narrows: all the cards, then the ones drawn. */
export const searchCount = (total, shown) => `${total} 件中 ${shown} 件`

/** The text of the session `me` from the view state's `filter` value; '' for none or another session's. */
export function filterOf(value, me) {
  if (value == null || typeof value !== 'object' || value.owner !== me) return ''
  return typeof value.text === 'string' ? value.text : ''
}

/** The `filter` value after the person typed `text`. Kept as typed (not trimmed); null once it is empty. */
export const filterAfter = (me, text) => (typeof text === 'string' && text !== '' ? { owner: me, text } : null)

// The surfaces that draw no Input field. The mobile app's element table still hands out an Input,
// but it draws as an empty Box there, so the surface is named rather than the table looked at.
const NO_INPUT = new Set(['mobile'])

// The field owns its text: it is drawn with no `value`, since a drawing that hands back what was
// typed a moment ago would put the field back to it and lose the keys typed since. To empty it the
// field is drawn under a new key (`searchGen` in the view, moved on at each clear), so it starts
// again empty.

/** The field's key for the view's `searchGen`: `search-input`, then `search-input-1` and on. */
export const inputKey = (gen) => (Number.isSafeInteger(gen) && gen > 0 ? 'search-input-' + gen : 'search-input')

/** The view with the filter let go and the field drawn anew (a new key); the same view when there is no filter. */
export const filterCleared = (view) => (view.filter == null ? view : { ...view, filter: null, searchGen: (Number.isSafeInteger(view.searchGen) ? view.searchGen : 0) + 1 })

/** Whether the pane draws the field: enough cards, and an Input the surface draws. */
export const hasSearch = (cards, ui, surface) =>
  Array.isArray(cards) && cards.length >= SEARCH_MIN && typeof ui?.Input === 'function' && !NO_INPUT.has(surface)

/** Whether `text` narrows at all: one word or more. */
export const isFiltering = (text) => queryTerms(text).length > 0

/** The cards of `cards` (in their order) holding every word of `text` in their title or body; all of them for no word. */
export function filterCards(cards, text) {
  const terms = queryTerms(text).map((t) => t.toLowerCase())
  if (terms.length === 0) return cards
  return cards.filter((c) => {
    const seen = (c.title + '\n' + c.body).toLowerCase()
    return terms.every((t) => seen.includes(t))
  })
}

files.hooks/order.js:
// The order of the cards in the pane (pure): the order they were added (the default), or the
// latest write first. A view only: the cards and their order on the board are never changed. The
// pinned cards come first in both orders; within the pinned and within the rest, the second order
// sorts by `updatedAt`, newest first, cards written at the same moment keeping the added order.
//
// The choice lives in the view state for the session (`order`: { owner, by }), so after /clear
// (another session id) it reads as the default, like the fold choices. The button is drawn with
// ORDER_MIN cards or more; with fewer the pane draws the added order whatever was chosen.

import { orderedCards } from './board.js'

/** The fewest cards that bring the order button. */
export const ORDER_MIN = 3

/** The button's label for each order: it names the order drawn now, a press switches it. */
export const ORDER_LABELS = { added: '並び: 追加順', updated: '並び: 更新の新しい順' }

/** The order of the session `me` from the view state's `order` value: 'updated', else 'added'. */
export const orderOf = (value, me) => (value != null && typeof value === 'object' && value.owner === me && value.by === 'updated' ? 'updated' : 'added')

/** The `order` value for the order `by`; null for the default. */
export const orderAfter = (me, by) => (by === 'updated' ? { owner: me, by: 'updated' } : null)

/** Whether the pane draws the button. */
export const hasOrder = (cards) => Array.isArray(cards) && cards.length >= ORDER_MIN

const timeOf = (card) => (typeof card.updatedAt === 'number' ? card.updatedAt : 0)

/** The cards as the pane draws them in the order `by`: the pinned first, then the rest. */
export function sortCards(cards, by) {
  const ordered = orderedCards(cards)
  if (by !== 'updated') return ordered
  const newest = (list) => [...list].sort((a, b) => timeOf(b) - timeOf(a))
  return [...newest(ordered.filter((c) => c.pinned === true)), ...newest(ordered.filter((c) => c.pinned !== true))]
}

files.hooks/stale.js:
// Cards that have gone stale: not pinned and not written for `staleHours` hours (the setting;
// 0 turns it off). The pane marks them with a dim 古い and draws their title dim, the band counts
// them (`· 古い N枚`, the first part to go on a narrow line), and list_cards' titles_only adds
// `stale: true`. Nothing is ever removed for it: the person (or Claude, when asked) decides.
// Pure: no $ here. The mark is worked out at each drawing from the clock's time; there is no timer,
// so it shows at the next redraw (a write, the person's next prompt, the pane opened again).

/** The setting's default: three hours. */
export const STALE_DEFAULT_HOURS = 3

const HOUR_MS = 60 * 60 * 1000

/**
 * The setting `staleHours` from register()'s options: a number of hours (a fraction will do), or
 * the same written as a string ("3", " 1.5 "). 0 turns the mark off. Anything else (absent, empty,
 * negative, not a number) is the default.
 */
export function staleHoursOf(options) {
  const raw = options?.staleHours
  const n = typeof raw === 'number' ? raw : typeof raw === 'string' && raw.trim() !== '' ? Number(raw.trim()) : NaN
  return Number.isFinite(n) && n >= 0 ? n : STALE_DEFAULT_HOURS
}

/**
 * Whether a card is stale at `now`: the mark is on (`hours` > 0), the card is not pinned, not
 * marked 新規 / 更新 in the current turn (`marked`), and the later of its last write and the time it
 * came in by a hand-over (`arrivedAt`, boards.js planHandover) is more than `hours` hours before
 * `now`. So a card taken over from an old board is fresh on arrival, while it keeps its own time
 * for display. A card or a time that cannot be read is never stale.
 */
export function isStaleCard(card, now, hours, marked = false) {
  if (!(typeof hours === 'number' && hours > 0) || marked) return false
  if (card == null || card.pinned === true || typeof card.updatedAt !== 'number' || typeof now !== 'number') return false
  const since = typeof card.arrivedAt === 'number' ? Math.max(card.updatedAt, card.arrivedAt) : card.updatedAt
  return now - since > hours * HOUR_MS
}

/** How many of the cards are stale; `marks` are the current turn's marks by id (recent.js). */
export const staleCount = (cards, now, hours, marks = {}) =>
  Array.isArray(cards) ? cards.filter((c) => isStaleCard(c, now, hours, marks[c?.id] !== undefined)).length : 0

/** The pane's word in a stale card's header. */
export const STALE_LABEL = '古い'

/** The band's word for the stale cards, `· 古い 2枚`. */
export const staleText = (n) => `· 古い ${n}枚`

files.hooks/press-guard.js:
// Runs a pane's Button press again when it did not reach the Button's onPress (the same file
// as in usage-ledger and ui-sampler, kept here so the mods do not depend on each other).
//
// A Button's onPress stays in this mod's environment under a handle the host holds for the
// life of one drawing. A pane is drawn again whenever its props change, so a press that comes
// in just as the drawing it was aimed at is replaced (the first click on an unfocused pane
// focuses it, and `isFocused` changes) can find its handle gone and never reach the closure.
//
// So each guarded drawing keeps its own Buttons' closures here, by requestId and key, and wraps
// each onPress so that a run of it is seen. The ui.press hook (pane.js) opens a press record
// before next(e); if the chain settles, fails, or stays silent past a grace without the
// Button's onPress having started, the hook takes the press over and runs the closure the
// latest drawing holds under the same key. A press runs at most once: a closure the engine
// starts after the take-over finds the record taken and does nothing.
//
// Pure: no $ here, so the hook files keep every $ call themselves.

/** How long the hook waits for the press to reach an onPress before it takes it over. */
export const GRACE_MS = 2000

// The closures of the latest finished drawing, by requestId, then key
const drawn = new Map()
// The press in flight per `requestId key`: { started, takenOver }
const pending = new Map()

const slot = (requestId, key) => requestId + ' ' + key

/**
 * Starts one drawing of the pane `requestId`. `wrap(table)` hands back the element table with
 * its Button keeping each onPress here; `done(tree)` makes this drawing the latest and returns
 * the tree. A drawing that fails before done() leaves the previous one in place.
 */
export function guardDrawing(requestId) {
  const handlers = new Map()
  return {
    wrap(table) {
      const Button = props => {
        const onPress = props.onPress
        if (typeof onPress !== 'function') return table.Button(props)
        handlers.set(props.key, onPress)
        return table.Button({ ...props, onPress: press => runGuarded(requestId, props.key, onPress, press) })
      }
      return { ...table, Button }
    },
    done(tree) {
      drawn.set(requestId, handlers)
      return tree
    },
  }
}

// The onPress the surface runs: marks the press as reached, unless the hook already took it
// over, in which case it does nothing (the press has run once already)
function runGuarded(requestId, key, onPress, press) {
  const record = pending.get(slot(requestId, key))
  if (record?.takenOver) return undefined
  if (record) record.started = true
  return onPress(press)
}

/**
 * Opens the record of one press before next(e). Undefined when the latest drawing of that
 * pane has no guarded Button under the key (another site, or a key this mod does not keep):
 * such a press is only watched.
 */
export function beginPress(e) {
  if (!drawn.get(e.requestId)?.has(e.element)) return undefined
  const record = { started: false, takenOver: false }
  pending.set(slot(e.requestId, e.element), record)
  return record
}

/** Whether the press has reached (started) its Button's onPress. */
export function hasStarted(record) {
  return record.started
}

/**
 * Takes the press over and runs the latest drawing's closure for its key with `press` (the
 * ui.press argument). Marks the record first, so the engine's own onPress, if it still
 * comes, does nothing. Resolves to what the closure returned.
 */
export function takeOver(record, press) {
  record.takenOver = true
  const onPress = drawn.get(press.requestId)?.get(press.element)
  return onPress ? onPress(press) : undefined
}

/**
 * Closes the record of a press the engine ran itself. A taken-over record stays until the
 * next press on the key replaces it, so the engine's own onPress, arriving late, still finds it.
 */
export function endPress(press, record) {
  const key = slot(press.requestId, press.element)
  if (!record.takenOver && pending.get(key) === record) pending.delete(key)
}

files.hooks/mermaid.js:
// A small mermaid drawer for the cards' ```mermaid fences (pure: no $ here).
//
// The desktop's Markdown shows a mermaid fence as a code block, so the ones this file can read
// are drawn as an SVG for the `Svg` element instead; anything else (another kind of diagram,
// something it cannot parse, a diagram too big) gives null and the fence stays a code block.
//
// Read: flowchart / graph with the directions TD TB BT LR RL; nodes `A`, `A[text]`, `A(text)`,
// `A((text))`, `A([text])`, `A{text}`, with quotes in the text allowed; edges `-->` `---` `-.->`
// `-.-` `==>` `===`, `-- text -->`, `-->|text|`; chains `A --> B --> C`; `A & B --> C`; `;` and
// newlines; `%%` comments; `style`, `classDef`, `class`, `linkStyle` and `click` lines are
// skipped. `subgraph id`, `subgraph id[title]`, `subgraph id["title"]`, `subgraph title words`
// up to `end`, nested, with `direction` inside one read but not followed. A node belongs to the
// innermost subgraph whose own lines mention it first (as mermaid: the subgraph closed first wins).
// An edge to or from a subgraph itself (`A --> sg1`) is not drawn: the diagram gives null, as do a
// `direction` outside a subgraph, an empty subgraph and any other syntax.
// Also sequenceDiagram with participants / actors and the arrows `->>` `-->>` `->` `-->` `-x`
// `--x` `-)` `--)` with a message; notes, loops, activations and the rest give null.
//
// Drawn: layers by the longest path (a cycle's back edge is drawn as a returning curve), nodes
// filled and edges and labels on their own small fills, so it reads on a light and a dark theme.
// A subgraph is a faint rounded box around its members with its title on a small fill in the band
// at the top of the box, left-most where no edge crosses it (a box whose band has no such place is
// widened and laid out again); its members are kept side by side in each layer and the boxes of
// one level are packed next to each other, so they never cross. If the boxes still came out
// crossing a node or each other, or a title still had no clear place, the diagram gives null
// rather than a misleading picture.

import { cells } from './board.js'

/** What a diagram may be at most; a bigger one is left as code. */
export const MERMAID_LIMITS = {
  nodes: 30,
  edges: 60,
  label: 80,
  messages: 40,
  subgraphs: 12,
}

// ---- Parsing

const ID = /^[A-Za-z0-9_぀-ヿ㐀-鿿０-９Ａ-Ｚａ-ｚ]+/

// The shapes: opener, closer, shape. The longer openers first
const SHAPES = [
  ['((', '))', 'circle'],
  ['([', '])', 'stadium'],
  ['[[', ']]', 'rect'],
  ['{{', '}}', 'rect'],
  ['[(', ')]', 'rect'],
  ['[', ']', 'rect'],
  ['(', ')', 'round'],
  ['{', '}', 'diamond'],
]

// The edge forms, the dotted and thick before the plain: [pattern, style, hasHead]
const CONNECTORS = [
  [/^-\.+->/, 'dotted', true],
  [/^-\.+-/, 'dotted', false],
  [/^={2,}>/, 'thick', true],
  [/^={3,}/, 'thick', false],
  [/^-{2,}>/, 'normal', true],
  [/^-{3,}/, 'normal', false],
]

// `-- text -->`: a start, the text, an end
const LABELLED = /^(--|==|-\.)\s+(.+?)\s+(\.+->|\.+-(?!>)|-\.+->|-\.+-|={2,}>|={3,}|-{2,}>|-{3,})/

/** A label as lines: <br> is a line break, quotes and blanks dropped. */
const labelOf = (t) =>
  String(t)
    .replace(/<br\s*\/?>/gi, '\n')
    .split('\n')
    .map((l) => l.trim())
    .filter((l, i, all) => l !== '' || all.length === 1)
    .join('\n')
    .trim()

// Splits a source into statements: newlines, and `;` outside brackets and quotes
function statementsOf(source) {
  const out = []
  for (const raw of String(source).split(/\r?\n/)) {
    let line = ''
    let depth = 0
    let quoted = false
    for (const ch of raw) {
      if (ch === '"') quoted = !quoted
      if (!quoted) {
        if ('[({'.includes(ch)) depth++
        if ('])}'.includes(ch)) depth = Math.max(0, depth - 1)
        if (ch === ';' && depth === 0) {
          out.push(line.trim())
          line = ''
          continue
        }
      }
      line += ch
    }
    out.push(line.trim())
  }
  return out.filter((s) => s !== '' && !s.startsWith('%%'))
}

// The shape at s[i], or null: { shape, text, end }
function shapeAt(s, i) {
  for (const [open, close, shape] of SHAPES) {
    if (!s.startsWith(open, i)) continue
    const k = i + open.length
    if (s[k] === '"') {
      const q = s.indexOf('"', k + 1)
      if (q < 0 || !s.startsWith(close, q + 1)) return null
      return { shape, text: s.slice(k + 1, q), end: q + 1 + close.length }
    }
    const c = s.indexOf(close, k)
    if (c < 0) return null
    return { shape, text: s.slice(k, c), end: c + close.length }
  }
  return null
}

// A node at s[i]: { id, text?, shape?, end }, or null
function nodeAt(s, i) {
  const m = ID.exec(s.slice(i))
  if (!m) return null
  let end = i + m[0].length
  const shaped = shapeAt(s, end)
  if (shaped) end = shaped.end
  const klass = /^:::[A-Za-z0-9_-]+/.exec(s.slice(end))
  if (klass) end += klass[0].length
  return { id: m[0], ...(shaped ? { text: shaped.text, shape: shaped.shape } : {}), end }
}

// An edge at s[i] (after blanks): { style, hasHead, label, end }, or null
function connectorAt(s, i) {
  const rest = s.slice(i)
  const named = LABELLED.exec(rest)
  if (named) {
    const style = named[1] === '==' ? 'thick' : named[1] === '-.' ? 'dotted' : 'normal'
    return { style, hasHead: named[3].endsWith('>'), label: named[2], end: i + named[0].length }
  }
  for (const [pattern, style, hasHead] of CONNECTORS) {
    const m = pattern.exec(rest)
    if (!m) continue
    let end = i + m[0].length
    let label = ''
    const piped = /^\s*\|([^|]*)\|/.exec(s.slice(end))
    if (piped) {
      label = piped[1]
      end += piped[0].length
    }
    return { style, hasHead, label, end }
  }
  return null
}

const skipBlanks = (s, i) => {
  while (s[i] === ' ' || s[i] === '\t') i++
  return i
}

const named = (id, title) => ({ id, label: labelOf(title).replace(/\n/g, ' ') || id })

// What follows `subgraph`: { id, label }, or null. `id`, `id[title]`, `id ["title"]`, `"title"`,
// and a bare title of several words, which is its own id (no edge can name it)
function subgraphHead(rest) {
  if (rest === '') return null
  const quoted = /^"([^"]*)"$/.exec(rest)
  if (quoted) return named(quoted[1], quoted[1])
  const m = ID.exec(rest)
  if (m) {
    const after = rest.slice(m[0].length).trim()
    if (after === '') return named(m[0], m[0])
    if (after.startsWith('[')) {
      const t = /^\[\s*(?:"([^"]*)"|([^\]"]*))\s*\]$/.exec(after)
      return t ? named(m[0], t[1] ?? t[2]) : null
    }
  }
  if (/[[\](){}"|]/.test(rest)) return null
  return named(rest, rest)
}

/** Parses a flowchart / graph; null when it is not one or uses what is not read. */
function parseFlowchart(source) {
  const statements = statementsOf(source)
  const header = /^(?:flowchart|graph)(?:\s+(TD|TB|BT|LR|RL))?$/i.exec(statements[0] ?? '')
  if (!header) return null
  const direction = (header[1] ?? 'TD').toUpperCase().replace('TB', 'TD')
  const nodes = []
  const edges = []
  // The subgraphs in the order they open: { id, label, parent, nodes }, nodes being the ones
  // directly in it; `open` are those not closed yet (innermost last), `owned` the nodes given out
  const subgraphs = []
  const open = []
  const mentioned = new Map()
  const owned = new Set()
  const find = (id) => nodes.find((n) => n.id === id)
  const note = (n) => {
    let node = find(n.id)
    if (!node) {
      if (nodes.length >= MERMAID_LIMITS.nodes) return null
      node = { id: n.id, label: n.id, shape: 'rect' }
      nodes.push(node)
    }
    if (n.text !== undefined) {
      node.label = labelOf(n.text) || n.id
      node.shape = n.shape
    }
    const inner = open.at(-1)
    if (inner && !mentioned.get(inner).includes(node.id)) mentioned.get(inner).push(node.id)
    return node
  }
  for (const s of statements.slice(1)) {
    if (/^(style|classDef|class|linkStyle|click)\b/.test(s)) continue
    if (/^subgraph\b/.test(s)) {
      const head = subgraphHead(s.slice('subgraph'.length).trim())
      if (!head || subgraphs.length >= MERMAID_LIMITS.subgraphs || subgraphs.some((g) => g.id === head.id)) return null
      const group = { ...head, parent: open.at(-1)?.id ?? null, nodes: [] }
      subgraphs.push(group)
      open.push(group)
      mentioned.set(group, [])
      continue
    }
    if (/^end\b/.test(s)) {
      if (s !== 'end' || open.length === 0) return null
      // The nodes its own lines mention that no subgraph closed before took
      const group = open.pop()
      group.nodes = mentioned.get(group).filter((id) => !owned.has(id))
      for (const id of group.nodes) owned.add(id)
      continue
    }
    if (/^direction\b/.test(s)) {
      // Read inside a subgraph, but the layout keeps the diagram's direction
      if (open.length === 0 || !/^direction\s+(TB|TD|BT|LR|RL)$/i.test(s)) return null
      continue
    }
    let i = 0
    let previous = null
    for (;;) {
      // A group of nodes: A & B & C
      const group = []
      for (;;) {
        i = skipBlanks(s, i)
        const n = nodeAt(s, i)
        if (!n) return null
        const node = note(n)
        if (!node) return null
        group.push(node)
        i = skipBlanks(s, n.end)
        if (s[i] === '&') {
          i++
          continue
        }
        break
      }
      if (previous) {
        for (const from of previous.group) {
          for (const to of group) edges.push({ from: from.id, to: to.id, ...previous.edge })
        }
      }
      if (i >= s.length) break
      const edge = connectorAt(s, i)
      if (!edge) return null
      previous = { group, edge: { style: edge.style, hasHead: edge.hasHead, label: labelOf(edge.label) } }
      i = edge.end
    }
    if (edges.length > MERMAID_LIMITS.edges) return null
  }
  if (nodes.length === 0 || nodes.some((n) => [...n.label].length > MERMAID_LIMITS.label)) return null
  if (edges.some((e) => [...e.label].length > MERMAID_LIMITS.label)) return null
  if (open.length > 0) return null
  // An edge to a subgraph itself (a node of its id) is not drawn; nor is a subgraph with no node
  if (subgraphs.some((g) => find(g.id) || [...g.label].length > MERMAID_LIMITS.label)) return null
  const holds = (g) => g.nodes.length > 0 || subgraphs.some((c) => c.parent === g.id && holds(c))
  if (!subgraphs.every(holds)) return null
  return { kind: 'flowchart', direction, nodes, edges, subgraphs }
}

const MESSAGE = /^([^\s:+-]+?)\s*(--?>>|--?>|--?x|--?\))\s*[+-]?\s*([^\s:]+?)\s*:\s*(.*)$/
const PARTICIPANT = /^(?:participant|actor)\s+([^\s]+)(?:\s+as\s+(.+))?$/

/** Parses a sequence diagram of participants and messages; null otherwise. */
function parseSequence(source) {
  const statements = statementsOf(source)
  if (!/^sequenceDiagram$/i.test(statements[0] ?? '')) return null
  const participants = []
  const messages = []
  const touch = (id, label) => {
    let p = participants.find((x) => x.id === id)
    if (!p) {
      if (participants.length >= MERMAID_LIMITS.nodes) return null
      p = { id, label: id }
      participants.push(p)
    }
    if (label) p.label = labelOf(label) || id
    return p
  }
  for (const s of statements.slice(1)) {
    const decl = PARTICIPANT.exec(s)
    if (decl) {
      if (!touch(decl[1], decl[2])) return null
      continue
    }
    const m = MESSAGE.exec(s)
    if (!m) return null
    if (!touch(m[1]) || !touch(m[3])) return null
    messages.push({ from: m[1], to: m[3], isDashed: m[2].startsWith('--'), hasHead: m[2].endsWith('>>') || m[2].endsWith('x') || m[2].endsWith(')'), text: labelOf(m[4]) })
    if (messages.length > MERMAID_LIMITS.messages) return null
  }
  if (participants.length === 0 || messages.length === 0) return null
  if (participants.some((p) => [...p.label].length > MERMAID_LIMITS.label)) return null
  return { kind: 'sequence', participants, messages }
}

/** The model of a mermaid source (a flowchart or a sequence diagram), or null for anything not read. */
export function parseMermaid(source) {
  try {
    return parseFlowchart(source) ?? parseSequence(source)
  } catch {
    return null
  }
}

// ---- Layout of a flowchart

const CHAR = 7 // pixels per character cell of the labels (13px type)
const LINE = 17 // pixels per line of a label

const linesOf = (label) => String(label).split('\n')
const textWidth = (label) => Math.max(...linesOf(label).map((l) => cells(l))) * CHAR

/** The pixel size of a node by its shape and label. */
export function sizeOf(node) {
  const w = textWidth(node.label) + 24
  const h = LINE * linesOf(node.label).length + 14
  if (node.shape === 'diamond') return { w: Math.max(56, w * 1.5), h: Math.max(44, h * 1.7) }
  if (node.shape === 'circle') return { w: Math.max(48, w * 1.25), h: Math.max(44, h * 1.5) }
  return { w: Math.max(40, w), h: Math.max(30, h) }
}

/**
 * Layers by the longest path, the edges that close a cycle left out of it:
 * { layers: id[][], isBack: Set of edge indexes, layerOf: Map }.
 */
export function layersOf(model) {
  const ids = model.nodes.map((n) => n.id)
  const out = new Map(ids.map((id) => [id, []]))
  model.edges.forEach((e, i) => {
    if (e.from !== e.to) out.get(e.from).push({ to: e.to, index: i })
  })
  // Depth first in the order the nodes appeared: an edge to a node still open is a back edge
  const state = new Map()
  const isBack = new Set()
  const visit = (id) => {
    state.set(id, 1)
    for (const { to, index } of out.get(id)) {
      if (state.get(to) === 1) isBack.add(index)
      else if (!state.has(to)) visit(to)
    }
    state.set(id, 2)
  }
  for (const id of ids) if (!state.has(id)) visit(id)
  const preds = new Map(ids.map((id) => [id, []]))
  model.edges.forEach((e, i) => {
    if (e.from !== e.to && !isBack.has(i)) preds.get(e.to).push(e.from)
  })
  const layerOf = new Map()
  const depth = (id) => {
    if (!layerOf.has(id)) layerOf.set(id, preds.get(id).reduce((m, p) => Math.max(m, depth(p) + 1), 0))
    return layerOf.get(id)
  }
  ids.forEach(depth)
  const layers = []
  for (const id of ids) (layers[layerOf.get(id)] ??= []).push(id)
  // With subgraphs, each subgraph's members are kept together in every layer after each step
  const regroup = groupOrder(model)
  if (regroup) layers.forEach((l, li) => (layers[li] = regroup(l)))
  // Order inside a layer by the mean place of the neighbours (two sweeps down and up)
  const place = new Map()
  const mark = () => layers.forEach((l) => l.forEach((id, k) => place.set(id, k)))
  mark()
  const succs = new Map(ids.map((id) => [id, []]))
  model.edges.forEach((e, i) => {
    if (e.from !== e.to && !isBack.has(i)) succs.get(e.from).push(e.to)
  })
  const sweep = (list, neighbours) => {
    const keyed = list.map((id, k) => {
      const near = neighbours.get(id)
      return { id, k, key: near.length ? near.reduce((s, n) => s + place.get(n), 0) / near.length : place.get(id) }
    })
    keyed.sort((a, b) => a.key - b.key || a.k - b.k)
    return keyed.map((x) => x.id)
  }
  const step = (list, neighbours) => (regroup ? regroup(sweep(list, neighbours)) : sweep(list, neighbours))
  for (let round = 0; round < 2; round++) {
    for (let l = 1; l < layers.length; l++) {
      layers[l] = step(layers[l], preds)
      mark()
    }
    for (let l = layers.length - 2; l >= 0; l--) {
      layers[l] = step(layers[l], succs)
      mark()
    }
  }
  return { layers, isBack, layerOf }
}

// The subgraphs a node is in, outermost first: Map id -> subgraph ids (none for a node outside)
function chainsOf(model) {
  const parent = new Map(model.subgraphs.map((g) => [g.id, g.parent]))
  const chains = new Map()
  for (const g of model.subgraphs) {
    const chain = []
    for (let at = g.id; at !== null; at = parent.get(at)) chain.unshift(at)
    for (const id of g.nodes) chains.set(id, chain)
  }
  return chains
}

// A function that reorders a layer so each subgraph's members are next to each other (nested
// ones inside theirs), the groups and the loose nodes ordered by their mean place; null without
// subgraphs
function groupOrder(model) {
  if (!model.subgraphs?.length) return null
  const chains = chainsOf(model)
  const arrange = (ids, depth) => {
    const order = []
    const byKey = new Map()
    ids.forEach((id, k) => {
      const chain = chains.get(id) ?? []
      const key = depth < chain.length ? 'g' + chain[depth] : 'n' + id
      if (!byKey.has(key)) {
        byKey.set(key, { isGroup: depth < chain.length, ids: [], sum: 0, first: order.length })
        order.push(byKey.get(key))
      }
      const g = byKey.get(key)
      g.ids.push(id)
      g.sum += k
    })
    order.sort((a, b) => a.sum / a.ids.length - b.sum / b.ids.length || a.first - b.first)
    return order.flatMap((g) => (g.isGroup ? arrange(g.ids, depth + 1) : g.ids))
  }
  return (list) => arrange(list, 0)
}

/**
 * Places the nodes: { boxes: Map id -> { x, y, w, h, shape, label } (centres), groups, layers,
 * isBack, layerOf }. `groups` are the subgraphs' boxes (see layoutGrouped), none without
 * subgraphs; null when they would not fit.
 */
export function layoutFlowchart(model, lanes = new Map()) {
  if (model.subgraphs?.length) return layoutGrouped(model, lanes)
  const { layers, isBack, layerOf } = layersOf(model)
  const isVertical = model.direction === 'TD' || model.direction === 'BT'
  const sizes = new Map(model.nodes.map((n) => [n.id, sizeOf(n)]))
  const main = (id) => (isVertical ? sizes.get(id).h : sizes.get(id).w)
  const cross = (id) => (isVertical ? sizes.get(id).w : sizes.get(id).h)
  const gapMain = isVertical ? 46 : 64
  const gapCross = 28
  const bandOf = layers.map((l) => Math.max(...l.map(main)))
  const totalOf = layers.map((l) => l.reduce((s, id) => s + cross(id), 0) + gapCross * (l.length - 1))
  const widest = Math.max(...totalOf)
  const length = bandOf.reduce((s, b) => s + b, 0) + gapMain * (layers.length - 1)
  const boxes = new Map()
  let at = 0
  layers.forEach((l, li) => {
    let c = (widest - totalOf[li]) / 2
    for (const id of l) {
      const m = at + bandOf[li] / 2
      const k = c + cross(id) / 2
      // BT and RL run the layers the other way
      const mm = model.direction === 'BT' || model.direction === 'RL' ? length - m : m
      const node = model.nodes.find((n) => n.id === id)
      boxes.set(id, { ...sizes.get(id), x: isVertical ? k : mm, y: isVertical ? mm : k, shape: node.shape, label: node.label })
      c += cross(id) + gapCross
    }
    at += bandOf[li] + gapMain
  })
  return { boxes, groups: [], layers, isBack, layerOf }
}

// ---- Layout of a flowchart with subgraphs

// A subgraph's box: the padding around its members (`top` on the title's side), the title chip
// in its top-left corner, and the room kept between a box's edge and what is outside it
const GROUP = { pad: 12, top: 34, chipX: 8, chipY: 6, chipH: 18, clear: 14 }
const chipWidth = (label) => textWidth(label) + 12
const titleRoom = (label) => chipWidth(label) + 2 * GROUP.chipX

/**
 * The layout with subgraphs. The layers and their order are those of layersOf (each subgraph's
 * members kept together); across the layers, the items of one level (the loose nodes and the
 * subgraphs) are packed in their order, a subgraph as one block over all the layers it covers,
 * so sibling boxes lie side by side; along the layers, the gaps grow to make room for the boxes'
 * padding. Each group: { id, label, parent, depth, members (all node ids inside), x, y, w, h
 * (top-left corner and size), chip: { x, y, w, h } }. Null when the result does not pass
 * groupsFit. `lanes` (subgraph id -> pixels) widens a box by that much on its starting side
 * across the title band (left for TD / BT, along the layers' start for LR / RL), its members kept
 * clear of it: the room placeChips finds for a title the edges left no gap for.
 */
function layoutGrouped(model, lanes = new Map()) {
  const { layers, isBack, layerOf } = layersOf(model)
  const isVertical = model.direction === 'TD' || model.direction === 'BT'
  const isReversed = model.direction === 'BT' || model.direction === 'RL'
  const sizes = new Map(model.nodes.map((n) => [n.id, sizeOf(n)]))
  const main = (id) => (isVertical ? sizes.get(id).h : sizes.get(id).w)
  const cross = (id) => (isVertical ? sizes.get(id).w : sizes.get(id).h)
  const gapMain = isVertical ? 46 : 64
  const gapCross = 28
  // A box's padding: along the layers (in their order, before flipping BT / RL) and across them;
  // the title's side gets `top`
  const padMainStart = model.direction === 'TD' ? GROUP.top : GROUP.pad
  const padMainEnd = model.direction === 'BT' ? GROUP.top : GROUP.pad
  const padCrossStart = isVertical ? GROUP.pad : GROUP.top
  const padCrossEnd = GROUP.pad

  // Where the plain layout would put each node across: it orders the items below
  const totalOf = layers.map((l) => l.reduce((s, id) => s + cross(id), 0) + gapCross * (l.length - 1))
  const widest = Math.max(...totalOf)
  const guess = new Map()
  layers.forEach((l, li) => {
    let c = (widest - totalOf[li]) / 2
    for (const id of l) {
      guess.set(id, c + cross(id) / 2)
      c += cross(id) + gapCross
    }
  })

  // Across: pack the items of one level, then place them
  const nodeIndex = new Map(model.nodes.map((n, i) => [n.id, i]))
  const owned = new Set(model.subgraphs.flatMap((g) => g.nodes))
  const childrenOf = (parent) => model.subgraphs.filter((g) => g.parent === parent)
  const descendants = new Map()
  const nodeItem = (id) => ({ id, ids: [id], width: cross(id) })
  const groupItem = (g) => {
    const inner = pack(itemsOf(g))
    const content = isVertical ? Math.max(inner.width, titleRoom(g.label) - padCrossStart - padCrossEnd) : inner.width
    const ids = inner.items.flatMap((it) => it.ids)
    descendants.set(g.id, ids)
    const lane = isVertical ? lanes.get(g.id) ?? 0 : 0
    return { id: g.id, group: g, ids, inner, width: padCrossStart + lane + content + padCrossEnd, offset: padCrossStart + lane + (content - inner.width) / 2 }
  }
  const itemsOf = (g) => [
    ...childrenOf(g ? g.id : null).map(groupItem),
    ...(g ? g.nodes : model.nodes.map((n) => n.id).filter((id) => !owned.has(id))).map(nodeItem),
  ]
  // Items in their order, each started as far as the others of its layers allow and no further
  // than where a centred row would put it
  function pack(items) {
    for (const it of items) {
      it.layers = [...new Set(it.ids.map((id) => layerOf.get(id)))]
      it.key = it.ids.reduce((s, id) => s + guess.get(id), 0) / it.ids.length
      it.first = Math.min(...it.ids.map((id) => nodeIndex.get(id)))
    }
    items.sort((a, b) => a.key - b.key || a.first - b.first)
    const total = new Map()
    for (const it of items) for (const l of it.layers) total.set(l, (total.has(l) ? total.get(l) + gapCross : 0) + it.width)
    const wide = Math.max(...total.values())
    const before = new Map()
    const frontier = new Map()
    for (const it of items) {
      let start = 0
      for (const l of it.layers) {
        start = Math.max(start, (wide - total.get(l)) / 2 + (before.get(l) ?? 0))
        if (frontier.has(l)) start = Math.max(start, frontier.get(l) + gapCross)
      }
      it.start = start
      for (const l of it.layers) {
        before.set(l, (before.get(l) ?? 0) + it.width + gapCross)
        frontier.set(l, start + it.width)
      }
    }
    return { items, width: Math.max(...items.map((it) => it.start + it.width)) }
  }
  const crossAt = new Map()
  const crossSpan = new Map()
  const place = (items, offset) => {
    for (const it of items) {
      const s = offset + it.start
      if (it.group) {
        crossSpan.set(it.id, [s, s + it.width])
        place(it.inner.items, s + it.offset)
      } else crossAt.set(it.id, s + it.width / 2)
    }
  }
  place(pack(itemsOf(null)).items, 0)

  // Along: the layers with the given gaps between them, and each box's extent along them
  const bandOf = layers.map((l) => Math.max(...l.map(main)))
  const lay = (gaps) => {
    const startOf = []
    let at = 0
    layers.forEach((_, li) => {
      startOf.push(at)
      at += bandOf[li] + (li < layers.length - 1 ? gaps[li] : 0)
    })
    const mainAt = (id) => startOf[layerOf.get(id)] + bandOf[layerOf.get(id)] / 2
    const span = new Map()
    const measure = (g) => {
      let lo = Infinity
      let hi = -Infinity
      for (const id of g.nodes) {
        lo = Math.min(lo, mainAt(id) - main(id) / 2)
        hi = Math.max(hi, mainAt(id) + main(id) / 2)
      }
      for (const c of childrenOf(g.id)) {
        const [a, b] = measure(c)
        lo = Math.min(lo, a)
        hi = Math.max(hi, b)
      }
      lo -= padMainStart + (isVertical ? 0 : lanes.get(g.id) ?? 0)
      hi += padMainEnd
      // Left to right, the title's width is along the layers: the box reaches past its last layer
      if (!isVertical) hi = Math.max(hi, lo + titleRoom(g.label))
      span.set(g.id, [lo, hi])
      return [lo, hi]
    }
    childrenOf(null).forEach(measure)
    return { startOf, length: at, mainAt, span }
  }
  const layersIn = (g) => descendants.get(g.id).map((id) => layerOf.get(id))
  const rough = lay(layers.slice(1).map(() => gapMain))
  const gaps = layers.slice(1).map((_, li) => {
    let over = 0
    let under = 0
    for (const g of model.subgraphs) {
      const [lo, hi] = rough.span.get(g.id)
      if (Math.max(...layersIn(g)) === li) over = Math.max(over, hi - (rough.startOf[li] + bandOf[li]))
      if (Math.min(...layersIn(g)) === li + 1) under = Math.max(under, rough.startOf[li + 1] - lo)
    }
    return Math.max(gapMain, over + under + GROUP.clear)
  })
  const final = lay(gaps)

  // On the screen: BT and RL run the layers the other way
  const flip = (m) => (isReversed ? final.length - m : m)
  const boxes = new Map()
  for (const node of model.nodes) {
    const m = flip(final.mainAt(node.id))
    const k = crossAt.get(node.id)
    boxes.set(node.id, { ...sizes.get(node.id), x: isVertical ? k : m, y: isVertical ? m : k, shape: node.shape, label: node.label })
  }
  const depthOf = (g) => (g.parent === null ? 0 : 1 + depthOf(model.subgraphs.find((p) => p.id === g.parent)))
  const groups = model.subgraphs.map((g) => {
    const [lo, hi] = final.span.get(g.id)
    const [a, b] = isReversed ? [final.length - hi, final.length - lo] : [lo, hi]
    const [c0, c1] = crossSpan.get(g.id)
    const box = isVertical ? { x: c0, y: a, w: c1 - c0, h: b - a } : { x: a, y: c0, w: b - a, h: c1 - c0 }
    const chip = { x: box.x + GROUP.chipX, y: box.y + GROUP.chipY, w: chipWidth(g.label), h: GROUP.chipH }
    return { id: g.id, label: g.label, parent: g.parent, depth: depthOf(g), members: descendants.get(g.id), ...box, chip }
  })
  groups.sort((p, q) => p.depth - q.depth)
  if (!groupsFit(boxes, groups)) return null
  return { boxes, groups, layers, isBack, layerOf }
}

/**
 * Whether the subgraphs' boxes can be drawn without misleading: each member node inside its box
 * and clear of its title chip, every other node outside it, a nested box inside its parent and
 * clear of the parent's chip, and boxes that are not nested apart from each other.
 */
export function groupsFit(boxes, groups) {
  const inside = (a, b) => a.x >= b.x && a.y >= b.y && a.x + a.w <= b.x + b.w && a.y + a.h <= b.y + b.h
  const meets = (a, b) => a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h
  const byId = new Map(groups.map((g) => [g.id, g]))
  const isAbove = (g, h) => {
    for (let at = h.parent; at !== null && at !== undefined; at = byId.get(at)?.parent) if (at === g.id) return true
    return false
  }
  for (const g of groups) {
    for (const [id, b] of boxes) {
      const r = { x: b.x - b.w / 2, y: b.y - b.h / 2, w: b.w, h: b.h }
      if (g.members.includes(id)) {
        if (!inside(r, g) || meets(r, g.chip)) return false
      } else if (meets(r, g)) return false
    }
    if (!inside(g.chip, g)) return false
    for (const h of groups) {
      if (h === g || isAbove(h, g)) continue
      if (isAbove(g, h)) {
        if (!inside(h, g) || meets(h, g.chip)) return false
      } else if (meets(g, h)) return false
    }
  }
  return true
}

// ---- Drawing

const esc = (s) =>
  String(s)
    .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g, '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;')

const FONT = "system-ui, -apple-system, 'Segoe UI', 'Hiragino Sans', 'Yu Gothic UI', 'Meiryo', sans-serif"
const COLOR = {
  nodeFill: '#eef2ff',
  nodeStroke: '#6475c9',
  nodeText: '#1e2340',
  line: '#7c869b',
  tagFill: '#f6f7fb',
  tagStroke: '#b8bfd2',
  tagText: '#2b3040',
  groupFill: '#6475c9',
  groupStroke: '#6475c9',
}

const n1 = (v) => Math.round(v * 10) / 10

// A label's lines as <text>, centred on (x, y)
function textAt(label, x, y, color) {
  const lines = linesOf(label)
  const top = y - ((lines.length - 1) * LINE) / 2 + 4.5
  return lines.map((l, i) => `<text x="${n1(x)}" y="${n1(top + i * LINE)}" text-anchor="middle" font-size="13" fill="${color}">${esc(l)}</text>`).join('')
}

// The point on a node's outline in the direction (dx, dy) from its centre
function edgePoint(box, dx, dy) {
  const hw = box.w / 2
  const hh = box.h / 2
  const len = Math.hypot(dx, dy) || 1
  const ux = dx / len
  const uy = dy / len
  let t
  if (box.shape === 'circle') t = 1 / Math.hypot(ux / hw, uy / hh)
  else if (box.shape === 'diamond') t = 1 / (Math.abs(ux) / hw + Math.abs(uy) / hh)
  else t = Math.min(hw / (Math.abs(ux) || 1e-9), hh / (Math.abs(uy) || 1e-9))
  return { x: box.x + ux * t, y: box.y + uy * t }
}

function nodeSvg(box) {
  const { x, y, w, h } = box
  const style = `fill="${COLOR.nodeFill}" stroke="${COLOR.nodeStroke}" stroke-width="1.5"`
  let shape
  if (box.shape === 'circle') shape = `<ellipse cx="${n1(x)}" cy="${n1(y)}" rx="${n1(w / 2)}" ry="${n1(h / 2)}" ${style}/>`
  else if (box.shape === 'diamond') {
    shape = `<polygon points="${n1(x)},${n1(y - h / 2)} ${n1(x + w / 2)},${n1(y)} ${n1(x)},${n1(y + h / 2)} ${n1(x - w / 2)},${n1(y)}" ${style}/>`
  } else {
    const r = box.shape === 'stadium' ? h / 2 : box.shape === 'round' ? 10 : 3
    shape = `<rect x="${n1(x - w / 2)}" y="${n1(y - h / 2)}" width="${n1(w)}" height="${n1(h)}" rx="${r}" ${style}/>`
  }
  return shape + textAt(box.label, x, y, COLOR.nodeText)
}

// A small arrowhead with its tip at (x, y), pointing along (dx, dy)
function headSvg(x, y, dx, dy) {
  const len = Math.hypot(dx, dy) || 1
  const ux = dx / len
  const uy = dy / len
  const bx = x - ux * 9
  const by = y - uy * 9
  return `<polygon points="${n1(x)},${n1(y)} ${n1(bx - uy * 4.5)},${n1(by + ux * 4.5)} ${n1(bx + uy * 4.5)},${n1(by - ux * 4.5)}" fill="${COLOR.line}"/>`
}

const tagSvg = (label, x, y) => {
  const w = textWidth(label) + 12
  const h = LINE * linesOf(label).length + 4
  return `<rect x="${n1(x - w / 2)}" y="${n1(y - h / 2)}" width="${n1(w)}" height="${n1(h)}" rx="4" fill="${COLOR.tagFill}" stroke="${COLOR.tagStroke}" stroke-width="1"/>` + textAt(label, x, y, COLOR.tagText)
}

// A subgraph's box, faint enough for nested ones to show, its title on a small fill
function groupSvg(g) {
  const { chip } = g
  return (
    `<rect x="${n1(g.x)}" y="${n1(g.y)}" width="${n1(g.w)}" height="${n1(g.h)}" rx="8" fill="${COLOR.groupFill}" fill-opacity="0.07" stroke="${COLOR.groupStroke}" stroke-opacity="0.6" stroke-width="1"/>` +
    `<rect x="${n1(chip.x)}" y="${n1(chip.y)}" width="${n1(chip.w)}" height="${n1(chip.h)}" rx="4" fill="${COLOR.tagFill}" stroke="${COLOR.tagStroke}" stroke-width="1"/>` +
    `<text x="${n1(chip.x + 6)}" y="${n1(chip.y + 13)}" font-size="12" font-weight="600" fill="${COLOR.tagText}">${esc(g.label)}</text>`
  )
}

// The rectangle of an edge's label drawn by tagSvg at (x, y)
const tagRect = (label, x, y) => {
  const w = textWidth(label) + 12
  const h = LINE * linesOf(label).length + 4
  return { x: x - w / 2, y: y - h / 2, w, h }
}

// Points along a quadratic (p0, c, p1) or a cubic (p0, c1, c2, p1) curve, ends included
function curvePoints(...ps) {
  const out = []
  for (let k = 0; k <= 16; k++) {
    const t = k / 16
    let row = ps
    while (row.length > 1) row = row.slice(1).map((p, i) => ({ x: row[i].x + (p.x - row[i].x) * t, y: row[i].y + (p.y - row[i].y) * t }))
    out.push(row[0])
  }
  return out
}

/** Whether the segment p–q meets the rectangle r ({ x, y, w, h }), its inside included. */
export function segmentMeetsRect(p, q, r) {
  // Liang–Barsky: clip the segment's parameter range to the rectangle's four sides
  let t0 = 0
  let t1 = 1
  const dx = q.x - p.x
  const dy = q.y - p.y
  const sides = [
    [-dx, p.x - r.x],
    [dx, r.x + r.w - p.x],
    [-dy, p.y - r.y],
    [dy, r.y + r.h - p.y],
  ]
  for (const [a, b] of sides) {
    if (a === 0) {
      if (b < 0) return false
      continue
    }
    const t = b / a
    if (a < 0) t0 = Math.max(t0, t)
    else t1 = Math.min(t1, t)
    if (t0 > t1) return false
  }
  return true
}

// The room kept between a title chip and an edge or an edge's label (the line's width, a head)
const CHIP_CLEAR = 4
// How many times a box is widened for its title before the diagram is left as code
const CHIP_ROUNDS = 3

/**
 * Moves each subgraph's title chip along its title band (the strip at the top of the box that no
 * node or inner box reaches) to the leftmost place where no edge and no edge label comes within
 * CHIP_CLEAR of it; the chip keeps its place when it is clear there already. Returns the groups
 * whose band has no such place.
 */
function placeChips(groups, routes, labels) {
  const blocked = []
  for (const g of groups) {
    const free = (x) => {
      const r = { x: x - CHIP_CLEAR, y: g.chip.y - CHIP_CLEAR, w: g.chip.w + 2 * CHIP_CLEAR, h: g.chip.h + 2 * CHIP_CLEAR }
      for (const route of routes) for (let i = 1; i < route.length; i++) if (segmentMeetsRect(route[i - 1], route[i], r)) return false
      return !labels.some((t) => t.x < r.x + r.w && r.x < t.x + t.w && t.y < r.y + r.h && r.y < t.y + t.h)
    }
    const first = g.x + GROUP.chipX
    const last = g.x + g.w - GROUP.chipX - g.chip.w
    let at = null
    for (let x = first; x <= last + 1e-6 && at === null; x += 2) if (free(x)) at = x
    if (at === null && last > first && free(last)) at = last
    if (at === null) blocked.push(g)
    else g.chip = { ...g.chip, x: at }
  }
  return blocked
}

/**
 * { source, width, height } of a flowchart's SVG, or null when its subgraphs do not fit. With
 * subgraphs, no edge is drawn across a title: a title the edges leave no room for widens its box
 * (layoutFlowchart's lanes) and the layout is made again, up to CHIP_ROUNDS times.
 */
function flowchartSvg(model) {
  let lanes = new Map()
  for (let round = 0; ; round++) {
    const layout = layoutFlowchart(model, lanes)
    if (!layout) return null
    const edges = edgesSvg(model, layout)
    const blocked = placeChips(layout.groups, edges.routes, edges.labels)
    if (blocked.length === 0) return groupsFit(layout.boxes, layout.groups) ? pictureOf(layout, edges) : null
    if (round === CHIP_ROUNDS) return null
    lanes = new Map(lanes)
    for (const g of blocked) lanes.set(g.id, (lanes.get(g.id) ?? 0) + titleRoom(g.label))
  }
}

// The picture of a layout and its edges: boxes behind, then lines, heads, nodes and labels
function pictureOf(layout, edges) {
  const { boxes, groups: frames } = layout
  const points = [...edges.points]
  const grow = (x, y) => points.push({ x, y })
  for (const b of boxes.values()) {
    grow(b.x - b.w / 2, b.y - b.h / 2)
    grow(b.x + b.w / 2, b.y + b.h / 2)
  }
  for (const g of frames) {
    grow(g.x, g.y)
    grow(g.x + g.w, g.y + g.h)
  }
  const nodes = [...boxes.values()].map(nodeSvg)
  return wrap(points, [...frames.map(groupSvg), ...edges.lines, ...edges.heads, ...nodes, ...edges.tags])
}

/**
 * The edges of a layout: their SVG parts (lines, heads, tags), the points the picture must hold,
 * and for placeChips the course of each edge as points (`routes`, curves sampled) and the
 * rectangles of their labels (`labels`).
 */
function edgesSvg(model, layout) {
  const { boxes, isBack, layerOf } = layout
  const parts = { lines: [], heads: [], tags: [], points: [], routes: [], labels: [] }
  const grow = (x, y) => parts.points.push({ x, y })
  // Edges between the same two nodes are spread to either side
  const groups = new Map()
  model.edges.forEach((e, i) => {
    const key = [e.from, e.to].sort().join('\u0000')
    groups.set(key, [...(groups.get(key) ?? []), i])
  })
  model.edges.forEach((e, i) => {
    const a = boxes.get(e.from)
    const b = boxes.get(e.to)
    const dash = e.style === 'dotted' ? ' stroke-dasharray="5 4"' : ''
    const width = e.style === 'thick' ? 3 : 1.5
    const stroke = `fill="none" stroke="${COLOR.line}" stroke-width="${width}"${dash}`
    if (e.from === e.to) {
      const x = a.x + a.w / 2
      parts.lines.push(`<path d="M ${n1(x)} ${n1(a.y - 7)} C ${n1(x + 34)} ${n1(a.y - 30)} ${n1(x + 34)} ${n1(a.y + 30)} ${n1(x)} ${n1(a.y + 7)}" ${stroke}/>`)
      parts.routes.push(curvePoints({ x, y: a.y - 7 }, { x: x + 34, y: a.y - 30 }, { x: x + 34, y: a.y + 30 }, { x, y: a.y + 7 }))
      if (e.hasHead) parts.heads.push(headSvg(x, a.y + 7, -1, 0.35))
      grow(x + 36, a.y - 30)
      grow(x + 36, a.y + 30)
      if (e.label) {
        parts.tags.push(tagSvg(e.label, x + 40 + textWidth(e.label) / 2, a.y))
        parts.labels.push(tagRect(e.label, x + 40 + textWidth(e.label) / 2, a.y))
        grow(x + 52 + textWidth(e.label), a.y)
      }
      return
    }
    const members = groups.get([e.from, e.to].sort().join('\u0000'))
    const spread = (members.indexOf(i) - (members.length - 1) / 2) * 30
    const span = Math.abs(layerOf.get(e.to) - layerOf.get(e.from))
    const bend = spread + (span > 1 ? 40 : 0) + (isBack.has(i) ? 30 : 0)
    // The bend is measured from the pair's own direction, so the two ways of a pair part
    const [first, second] = [e.from, e.to].sort()
    const p = boxes.get(first)
    const q = boxes.get(second)
    const len = Math.hypot(q.x - p.x, q.y - p.y) || 1
    const nx = -(q.y - p.y) / len
    const ny = (q.x - p.x) / len
    const cx = (a.x + b.x) / 2 + nx * bend
    const cy = (a.y + b.y) / 2 + ny * bend
    const isCurved = bend !== 0
    const start = edgePoint(a, (isCurved ? cx : b.x) - a.x, (isCurved ? cy : b.y) - a.y)
    const end = edgePoint(b, (isCurved ? cx : a.x) - b.x, (isCurved ? cy : a.y) - b.y)
    parts.lines.push(isCurved ? `<path d="M ${n1(start.x)} ${n1(start.y)} Q ${n1(cx)} ${n1(cy)} ${n1(end.x)} ${n1(end.y)}" ${stroke}/>` : `<line x1="${n1(start.x)}" y1="${n1(start.y)}" x2="${n1(end.x)}" y2="${n1(end.y)}" ${stroke}/>`)
    parts.routes.push(isCurved ? curvePoints(start, { x: cx, y: cy }, end) : [start, end])
    if (e.hasHead) parts.heads.push(isCurved ? headSvg(end.x, end.y, end.x - cx, end.y - cy) : headSvg(end.x, end.y, end.x - start.x, end.y - start.y))
    if (isCurved) {
      grow(cx, cy)
      grow(start.x, start.y)
      grow(end.x, end.y)
    }
    if (e.label) {
      const mx = isCurved ? 0.25 * start.x + 0.5 * cx + 0.25 * end.x : (start.x + end.x) / 2
      const my = isCurved ? 0.25 * start.y + 0.5 * cy + 0.25 * end.y : (start.y + end.y) / 2
      parts.tags.push(tagSvg(e.label, mx, my))
      parts.labels.push(tagRect(e.label, mx, my))
      grow(mx - textWidth(e.label) / 2 - 8, my - 12)
      grow(mx + textWidth(e.label) / 2 + 8, my + 12)
    }
  })
  return parts
}

// The document around drawn parts: the points' box with a margin, the origin moved to it
function wrap(points, body) {
  const pad = 12
  const minX = Math.min(...points.map((p) => p.x)) - pad
  const minY = Math.min(...points.map((p) => p.y)) - pad
  const width = Math.ceil(Math.max(...points.map((p) => p.x)) + pad - minX)
  const height = Math.ceil(Math.max(...points.map((p) => p.y)) + pad - minY)
  const source =
    `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="${n1(minX)} ${n1(minY)} ${width} ${height}" font-family="${esc(FONT)}">` + body.join('') + '</svg>'
  return { source, width, height }
}

/** { source, width, height } of a sequence diagram's SVG. */
function sequenceSvg(model) {
  const ps = model.participants
  const boxW = ps.map((p) => Math.max(72, textWidth(p.label) + 24))
  const index = new Map(ps.map((p, i) => [p.id, i]))
  // The distance between the lifelines: wide enough for the boxes and for each message's text
  const x = [boxW[0] / 2]
  const need = ps.map(() => 0)
  for (let i = 1; i < ps.length; i++) need[i] = Math.max(110, (boxW[i - 1] + boxW[i]) / 2 + 24)
  const spans = model.messages
    .map((m) => ({ a: Math.min(index.get(m.from), index.get(m.to)), b: Math.max(index.get(m.from), index.get(m.to)), w: textWidth(m.text) + 36 }))
    .filter((s) => s.a !== s.b)
    .sort((s, t) => s.b - s.a - (t.b - t.a))
  for (const s of spans) {
    let have = 0
    for (let i = s.a + 1; i <= s.b; i++) have += need[i]
    if (have < s.w) need[s.b] += s.w - have
  }
  for (let i = 1; i < ps.length; i++) x.push(x[i - 1] + need[i])
  const headH = 32
  const rowH = 38
  const bottom = headH + 24 + model.messages.length * rowH + 8
  const body = []
  const points = [{ x: 0, y: 0 }]
  ps.forEach((p, i) => {
    body.push(`<line x1="${n1(x[i])}" y1="${headH}" x2="${n1(x[i])}" y2="${bottom}" stroke="${COLOR.line}" stroke-width="1" stroke-dasharray="4 4"/>`)
  })
  model.messages.forEach((m, k) => {
    const y = headH + 24 + k * rowH + rowH / 2
    const a = x[index.get(m.from)]
    const b = x[index.get(m.to)]
    const dash = m.isDashed ? ' stroke-dasharray="6 4"' : ''
    const stroke = `fill="none" stroke="${COLOR.line}" stroke-width="1.5"${dash}`
    if (a === b) {
      body.push(`<path d="M ${n1(a)} ${n1(y - 6)} C ${n1(a + 44)} ${n1(y - 8)} ${n1(a + 44)} ${n1(y + 12)} ${n1(a)} ${n1(y + 10)}" ${stroke}/>`)
      if (m.hasHead) body.push(headSvg(a, y + 10, -1, 0))
      if (m.text) body.push(tagSvg(m.text, a + 52 + textWidth(m.text) / 2, y))
      points.push({ x: a + 56 + textWidth(m.text), y })
      return
    }
    const dir = b > a ? 1 : -1
    body.push(`<line x1="${n1(a)}" y1="${n1(y)}" x2="${n1(b)}" y2="${n1(y)}" ${stroke}/>`)
    if (m.hasHead) body.push(headSvg(b, y, dir, 0))
    if (m.text) body.push(tagSvg(m.text, (a + b) / 2, y - 12))
  })
  // The participants' boxes, above and below the lifelines
  for (const top of [0, bottom]) {
    ps.forEach((p, i) => {
      body.push(nodeSvg({ x: x[i], y: top + headH / 2, w: boxW[i], h: headH - 4, shape: 'rect', label: p.label.replace(/\n/g, ' ') }))
    })
  }
  points.push({ x: x[ps.length - 1] + boxW[ps.length - 1] / 2, y: bottom + headH })
  return wrap(points, body)
}

// The drawings of the latest sources, by source (null kept too): the pane draws every card at each
// redraw, and a source drawn once is not parsed and laid out again. A Map keeps the order of
// insertion; a hit moves to the end, and past MERMAID_MEMO the oldest goes
const MERMAID_MEMO = 32
const drawings = new Map()

/**
 * The drawing of a mermaid source: { source, width, height, alt }, or null when it is not one this
 * file can draw. The same source gives the same object back while it is among the latest
 * MERMAID_MEMO drawn (do not change it).
 */
export function mermaidSvg(source) {
  const key = String(source)
  if (drawings.has(key)) {
    const hit = drawings.get(key)
    drawings.delete(key)
    drawings.set(key, hit)
    return hit
  }
  const drawn = drawMermaid(key)
  drawings.set(key, drawn)
  if (drawings.size > MERMAID_MEMO) drawings.delete(drawings.keys().next().value)
  return drawn
}

// mermaidSvg without the memo
function drawMermaid(source) {
  const model = parseMermaid(source)
  if (!model) return null
  try {
    const drawn = model.kind === 'flowchart' ? flowchartSvg(model) : sequenceSvg(model)
    if (!drawn || !Number.isFinite(drawn.width) || !Number.isFinite(drawn.height) || drawn.source.length > 100_000) return null
    return { ...drawn, alt: altOf(model) }
  } catch {
    return null
  }
}

/** What the drawing says in words, for a reader that cannot see it. */
export function altOf(model) {
  const flat = (s) => String(s).replace(/\n/g, ' ')
  const labelOfNode = (id) => flat(model.nodes.find((n) => n.id === id).label)
  // A subgraph in words: its title and what is directly in it
  const groupText = (g) => `${g.label}（${[...model.subgraphs.filter((c) => c.parent === g.id).map((c) => c.label), ...g.nodes.map(labelOfNode)].join('、')}）`
  const groups = model.subgraphs?.length ? ' / グループ: ' + model.subgraphs.map(groupText).join('、') : ''
  const text =
    model.kind === 'flowchart'
      ? 'フローチャート: ' + model.nodes.map((n) => flat(n.label)).join('、') + ' / ' + model.edges.map((e) => `${flat(model.nodes.find((n) => n.id === e.from).label)} → ${flat(model.nodes.find((n) => n.id === e.to).label)}${e.label ? `（${flat(e.label)}）` : ''}`).join('、') + groups
      : 'シーケンス図: ' +
        model.messages
          .map((m) => `${flat(model.participants.find((p) => p.id === m.from).label)} → ${flat(model.participants.find((p) => p.id === m.to).label)}${m.text ? `: ${flat(m.text)}` : ''}`)
          .join('、')
  return text.length > 300 ? text.slice(0, 299) + '…' : text
}

// ---- Fences in a body

/**
 * A card's body as pieces: { type: 'md', text } and { type: 'mermaid', source, raw }. Only a
 * ```mermaid fence (``` or ~~~) is its own piece; another fence is kept whole inside the text, so
 * a mermaid fence shown inside it is left alone. A fence never closed stays text.
 */
export function splitFences(body) {
  const lines = String(body).split('\n')
  const pieces = []
  let buffer = []
  const flush = () => {
    if (buffer.length > 0) pieces.push({ type: 'md', text: buffer.join('\n') })
    buffer = []
  }
  let i = 0
  while (i < lines.length) {
    const open = /^ {0,3}(`{3,}|~{3,})\s*([^\s`]*)\s*$/.exec(lines[i].replace(/\r$/, ''))
    if (!open) {
      buffer.push(lines[i++])
      continue
    }
    const fence = open[1]
    let closed = -1
    for (let j = i + 1; j < lines.length; j++) {
      const m = /^ {0,3}(`{3,}|~{3,})\s*$/.exec(lines[j].replace(/\r$/, ''))
      if (m && m[1][0] === fence[0] && m[1].length >= fence.length) {
        closed = j
        break
      }
    }
    if (closed < 0) {
      buffer.push(...lines.slice(i))
      break
    }
    if (open[2].toLowerCase() === 'mermaid') {
      flush()
      pieces.push({ type: 'mermaid', source: lines.slice(i + 1, closed).join('\n'), raw: lines.slice(i, closed + 1).join('\n') })
    } else {
      buffer.push(...lines.slice(i, closed + 1))
    }
    i = closed + 1
  }
  flush()
  return pieces
}

